PC_PLOT = ['Протон, влетевший в однородное магнитное поле электромагнита перпендикулярно линиям индукции, описывает окружность.',
           'В вакуумной камере протон обращается по окружности в однородном магнитном поле.',
           'В масс-спектрометре протон описывает дугу окружности в однородном магнитном поле, вектор скорости перпендикулярен вектору индукции.',
           'Пучок протонов, попав в однородное магнитное поле перпендикулярно линиям индукции, закручивается по окружности.']


def _solve_pc(p):
    def st(m, q, v, B):
        R = m * v / (q * B)
        T = 2 * math.pi * R / v
        return {'R': R, 'T': T, 'nu': 1 / T, 'F': q * v * B, 'a': v * v / R, 'Ek': m * v * v / 2}
    x = {'m': 1.0, 'q': 1.0, 'v': 1.0, 'B': 1.0}
    y = dict(x)
    for k, f in p['ch'].items():
        y[k] = x[k] * float(Fr(f))
    a, b = st(**x), st(**y)
    return {'А': chg(a[p['A']], b[p['A']]), 'Б': chg(a[p['B']], b[p['B']])}


@proto('ph-ege-15-particle-change', 'ЕГЭ', 15, 'Частица в магнитном поле: как изменятся радиус, период, сила Лоренца, ускорение',
       invariant='R = mv/(qB), T = 2πm/(qB), F = qvB, a = qvB/m',
       varies='сюжет, что меняют (скорость, индукцию, частицу: протон → α-частица/дейтрон), пара величин',
       answer_rule='две цифры 1/2/3 по буквам А, Б',
       mistakes=['период зависит от скорости', 'для α-частицы забывают удвоенный заряд'],
       solve=_solve_pc, kes=['3.3.4'],
       fidelity=fid('две цифры 1/2/3', 'КИМ: «Протон движется по окружности… Как изменятся…»', 'Б', 3, 'качественно, как в банке',
                    'T не зависит от v; m/q α-частицы вдвое больше', ['3.3.4'], SC_MATCH))
def g15_pc(rng):
    key = rng.choice(list(PC_CH))
    txt, ch = PC_CH[key]
    A, B = rng.sample(list(PC_Q), 2)
    if key in ('alpha', 'deut') and 'Ek' in (A, B):
        raise Retry
    # генератор: показатели степени R ∝ m v q⁻¹ B⁻¹ и т. д.
    expo = {'R': {'m': 1, 'v': 1, 'q': -1, 'B': -1}, 'T': {'m': 1, 'q': -1, 'B': -1}, 'nu': {'m': -1, 'q': 1, 'B': 1},
            'F': {'q': 1, 'v': 1, 'B': 1}, 'a': {'q': 1, 'v': 1, 'B': 1, 'm': -1}, 'Ek': {'m': 1, 'v': 2}}
    def ratio(Q):
        r = Fr(1)
        for k, f in ch.items():
            r *= Fr(f) ** expo[Q].get(k, 0)
        return r
    ans = {'А': _code(ratio(A)), 'Б': _code(ratio(B))}
    q = f'{rng.choice(PC_PLOT)} {txt} Как изменятся {PC_Q[A]} и {PC_Q[B]}? {Q_CHANGE}'
    e = f'R = mv/(qB), T = 2πm/(qB), F = qvB, a = F/m. {cap1(PC_Q[A])} — {CH[ans["А"]]}, {PC_Q[B]} — {CH[ans["Б"]]}. Ответ: {ans["А"]}{ans["Б"]}.'
    return change_card('ph-ege-15-particle-change', q, [PC_Q[A], PC_Q[B]], ans, e, {'ch': {k: fr(v) for k, v in ch.items()}, 'A': A, 'B': B})


# ---------- 15-lc-change: настройка контура

LC_Q = {'T': 'период собственных колебаний контура', 'nu': 'частота собственных колебаний контура',
        'lam': 'длина электромагнитной волны, соответствующая собственной частоте контура', 'W': 'максимальная энергия электрического поля конденсатора',
        'Im': 'амплитуда силы тока в катушке', 'qm': 'амплитуда заряда конденсатора'}
LC_CH = {'C+': ('электроёмкость конденсатора увеличивают', {'C': 2}), 'C-': ('электроёмкость конденсатора уменьшают', {'C': Fr(1, 2)}),
         'L+': ('индуктивность катушки увеличивают', {'L': 2}), 'L-': ('индуктивность катушки уменьшают', {'L': Fr(1, 2)})}
LCC_PLOT = ['При настройке колебательного контура радиопередатчика {ch}.', 'В модели радиопередатчика учитель {ch2}.',
           'При настройке контура генератора, задающего частоту излучения, {ch}.', 'В колебательном контуре радиоприёмника {ch}.']


def _solve_lcch(p):
    def st(L, C):
        T = 2 * math.pi * math.sqrt(L * C)
        Um = 1.0
        return {'T': T, 'nu': 1 / T, 'lam': 3e8 * T, 'W': C * Um ** 2 / 2, 'Im': Um * math.sqrt(C / L), 'qm': C * Um}
    x = {'L': 1.0, 'C': 1.0}
    y = dict(x)
    for k, f in p['ch'].items():
        y[k] *= float(Fr(f))
    a, b = st(**x), st(**y)
    return {'А': chg(a[p['A']], b[p['A']]), 'Б': chg(a[p['B']], b[p['B']])}


