    ans = {'А': rule[A], 'Б': rule[B]}
    verb = rng.choice(['переходит', 'проходит'])
    q = (f'{rng.choice(["Монохроматический световой пучок", "Узкий пучок лазерного излучения", "Плоская монохроматическая световая волна"])} '
         f'{verb} из {MED_FROM[m1]} в {MED_TO[m2]}. Как изменятся при этом {RF_Q[A]} и {RF_Q[B]}? {Q_CHANGE}')
    e = (f'n({m1}) = {MEDIA_N[m1]}, n({m2}) = {MEDIA_N[m2]}. Частота, период и энергия фотона не меняются; v = c/n и λ = v/ν '
         f'{"уменьшаются" if denser else "увеличиваются"}. Ответ: {ans["А"]}{ans["Б"]}.')
    return change_card('ph-ege-15-refraction-change', q, [RF_Q[A], RF_Q[B]], ans, e, {'m1': m1, 'm2': m2, 'A': A, 'B': B})


