LN_Q = {'f': 'расстояние между линзой и изображением', 'h': 'высота изображения', 'D': 'оптическая сила',
        'L': 'расстояние между предметом и его изображением', 'F': 'фокусное расстояние'}
LN_SIT = {
    'far_away': ('собирающей', 'находится за двойным фокусом', 'Предмет отодвигают от линзы.', 3, 4),
    'far_close': ('собирающей', 'находится между фокусом и двойным фокусом', 'Предмет немного приближают к фокусу, оставляя его за фокусом.', Fr(3, 2), Fr(5, 4)),
    'mag_close': ('собирающей', 'находится между линзой и её фокусом', 'Предмет приближают к линзе.', Fr(1, 2), Fr(1, 4)),
    'div_away': ('рассеивающей', 'находится на расстоянии, большем фокусного', 'Предмет отодвигают от линзы.', 2, 3),
    'div_close': ('рассеивающей', 'находится на расстоянии двойного фокуса', 'Предмет приближают к линзе.', 2, 1),
}
LN_PLOT = ['Небольшой предмет', 'Горящая свеча', 'Светящаяся стрелка', 'Карандаш']


def _solve_ln(p):
    kind, d1, d2 = LN_SIT[p['sit']][0], float(Fr(p['d1'])), float(Fr(p['d2']))
    F = 1.0 if kind == 'собирающей' else -1.0
    def st(d):
        f = 1 / (1 / F - 1 / d)
        return {'f': abs(f), 'h': abs(f) / d, 'D': 1 / F, 'L': d + f if f > 0 else abs(d - abs(f)), 'F': abs(F)}
    a, b = st(d1), st(d2)
    return {'А': chg(a[p['A']], b[p['A']]), 'Б': chg(a[p['B']], b[p['B']])}


