@proto('ph-ege-15-formula-circuit', 'ЕГЭ', 15, 'Цепь постоянного тока: соответствие величин и формул для их расчёта',
       invariant='закон Ома для полной цепи, правила соединений, P = I²R — выражение величины через ℰ, r, R₁, R₂',
       varies='последовательное/параллельное соединение, какие две величины спрашивают, формулы-дистракторы, описание источника',
       answer_rule='две цифры — номера формул для величин А и Б',
       mistakes=['формула без внутреннего сопротивления', 'путают мощность внутри источника и во внешней цепи'],
       solve=_solve_formula, kes=['3.2.6', '3.2.7', '3.2.9'],
       fidelity=fid('две цифры (номера формул)', 'КИМ: «Установите соответствие между физическими величинами и формулами, по которым их можно рассчитать»',
                    'Б', 3, 'буквенные формулы как в банке', 'выбор формулы с учётом r', ['3.2.6', '3.2.7', '3.2.9'], SC_MATCH))
def g15_fcirc(rng):
    par = rng.random() < 0.4
    src = rng.choice(['источнику тока', 'аккумулятору', 'батарее гальванических элементов'])
    how = 'параллельно' if par else 'последовательно'
    load = 'два резистора'
    q = (f'Внешняя цепь, подключённая к {src}, состоит из {({"два резистора": "двух резисторов", "две лампы": "двух ламп", "два нагревательных элемента": "двух нагревательных элементов"})[load]}, '
         f'соединённых {how}; их сопротивления R₁ и R₂. ЭДС источника ℰ, его внутреннее сопротивление r. '
         f'Установите соответствие между физическими величинами и формулами, по которым их можно рассчитать (сопротивлением проводов пренебречь).' + TAIL)
    if par:
        return formula_card('ph-ege-15-formula-circuit', rng, q, CIRC_Q_PAR, CIRC_FORMS_PAR, CIRC_REF_PAR, _envs(rng, ['E', 'r', 'R1', 'R2']))
    return formula_card('ph-ege-15-formula-circuit', rng, q, CIRC_Q_SER, CIRC_FORMS_SER, CIRC_REF_SER, _envs(rng, ['E', 'r', 'R1', 'R2']))


PF_FORMS = {'R': ('mυ/(qB)', 'm*v/(q*B)'), 'T': ('2πm/(qB)', '2*pi*m/(q*B)'), 'nu': ('qB/(2πm)', 'q*B/(2*pi*m)'),
            'p': ('mυ', 'm*v'), 'F': ('qυB', 'q*v*B'), 'a': ('qυB/m', 'q*v*B/m'), 'x1': ('qB/(mυ)', 'q*B/(m*v)'),
            'x2': ('2πmυ/(qB)', '2*pi*m*v/(q*B)'), 'x3': ('mυ²/(qB)', 'm*v**2/(q*B)')}
PF_REF = {'R': '(m*v**2/(q*v*B))', 'T': '2*pi*(m*v/(q*B))/v', 'nu': 'v/(2*pi*(m*v/(q*B)))', 'p': 'v*m', 'F': 'B*q*v',
          'a': 'v**2/(m*v/(q*B))', 'x1': '0', 'x2': '0', 'x3': '0'}
PF_Q = [('радиус траектории', 'R'), ('период обращения', 'T'), ('частота обращения', 'nu'), ('модуль импульса частицы', 'p'),
        ('модуль силы Лоренца', 'F'), ('модуль ускорения частицы', 'a')]


@proto('ph-ege-15-formula-particle', 'ЕГЭ', 15, 'Частица в магнитном поле: соответствие величин и формул',
       invariant='из qυB = mυ²/R: R = mυ/(qB), T = 2πm/(qB), ν = qB/(2πm), a = qυB/m',
       varies='частица (протон, ион, электрон…), пара величин, формулы-дистракторы',
       answer_rule='две цифры — номера формул для А и Б',
       mistakes=['R = qB/(mυ)', 'T с множителем υ'],
       solve=_solve_formula, kes=['3.3.4'],
       fidelity=fid('две цифры', 'КИМ: «Частица массой m, несущая заряд q, движется… Установите соответствие…»', 'Б', 3,
                    'буквенные формулы', 'вывод R и T из II закона Ньютона', ['3.3.4'], SC_MATCH))
def g15_fpart(rng):
    who = rng.choice(['протон', 'ион', 'позитрон', 'α-частица', 'дейтрон'])
    q = (f'В однородном магнитном поле индукцией B {who} (масса m, заряд q) обращается по окружности; его скорость υ лежит в плоскости, '
         f'перпендикулярной вектору индукции. Силой тяжести пренебречь. '
         f'Установите соответствие между физическими величинами и формулами, по которым их можно рассчитать (все величины — для этой частицы).' + TAIL)
    q = q.replace('его скорость', 'её скорость') if who == 'α-частица' else q
    return formula_card('ph-ege-15-formula-particle', rng, q, PF_Q, PF_FORMS, PF_REF, _envs(rng, ['m', 'q', 'v', 'B']))


LF_FORMS = {'qm': ('CUₘ', 'C*U'), 'Im': ('Uₘ√(C/L)', 'U*sqrt(C/L)'), 'T': ('2π√(LC)', '2*pi*sqrt(L*C)'), 'W': ('CUₘ²/2', 'C*U**2/2'),
            'nu': ('1/(2π√(LC))', '1/(2*pi*sqrt(L*C))'), 'x1': ('Uₘ√(L/C)', 'U*sqrt(L/C)'), 'x2': ('LUₘ²/2', 'L*U**2/2'),
            'x3': ('2π√(L/C)', '2*pi*sqrt(L/C)'), 'x4': ('Uₘ/C', 'U/C')}
LF_REF = {'qm': 'U*C', 'Im': 'sqrt(2*(C*U*U/2)/L)', 'T': '2*pi/(1/sqrt(L*C))', 'W': 'U*(C*U)/2', 'nu': '(1/sqrt(L*C))/(2*pi)',
          'x1': '0', 'x2': '0', 'x3': '0', 'x4': '0'}
LF_Q = [('амплитуда заряда конденсатора', 'qm'), ('амплитуда силы тока в катушке', 'Im'), ('период колебаний', 'T'),
        ('полная энергия колебаний', 'W'), ('частота колебаний', 'nu')]


@proto('ph-ege-15-formula-lc', 'ЕГЭ', 15, 'Колебательный контур: соответствие величин и формул (L, C, Uₘ)',
       invariant='qₘ = CUₘ; CUₘ²/2 = LIₘ²/2; T = 2π√(LC)',
       varies='сюжет контура, пара величин, формулы-дистракторы',
       answer_rule='две цифры — номера формул для А и Б',
       mistakes=['Iₘ = Uₘ√(L/C)', 'энергия через L вместо C'],
       solve=_solve_formula, kes=['3.5.1', '3.5.2'],
       fidelity=fid('две цифры', 'КИМ: «Идеальный колебательный контур состоит из… Установите соответствие…»', 'Б', 3, 'буквенные формулы',
                    'закон сохранения энергии в контуре', ['3.5.1', '3.5.2'], SC_MATCH))
def g15_flc(rng):
    who = rng.choice(['Идеальный колебательный контур состоит из конденсатора ёмкостью C и катушки индуктивностью L.',
                      'Контур радиоприёмника (идеальный) образован катушкой индуктивностью L и конденсатором ёмкостью C.',
                      'В идеальном LC-контуре катушка имеет индуктивность L, конденсатор — ёмкость C.'])
    q = (f'{who} Амплитуда напряжения на конденсаторе при свободных колебаниях равна Uₘ. '
         f'Установите соответствие между физическими величинами и формулами, по которым их можно рассчитать. К каждой позиции первого столбца подберите соответствующую позицию из второго столбца и запишите в таблицу выбранные цифры под соответствующими буквами.')
    return formula_card('ph-ege-15-formula-lc', rng, q, LF_Q, LF_FORMS, LF_REF, _envs(rng, ['L', 'C', 'U']))


# ---------- 15-lc-graph: какой величине соответствует таблица значений (вместо графика)

LG_SHAPES = {'q': 'заряд левой обкладки конденсатора', 'i': 'модуль силы тока в катушке', 'WC': 'энергия электрического поля конденсатора',
             'WL': 'энергия магнитного поля катушки', 'U': 'модуль напряжения на конденсаторе'}


def _lg_values(key):
    """Табличные значения (в долях максимума) в моменты 0, T/8, …, T для каждой величины — генератор (по таблице)."""
    return {'q': ['1', '0,71', '0', '−0,71', '−1', '−0,71', '0', '0,71', '1'],
            'i': ['0', '0,71', '1', '0,71', '0', '0,71', '1', '0,71', '0'],
            'WC': ['1', '0,5', '0', '0,5', '1', '0,5', '0', '0,5', '1'],
            'WL': ['0', '0,5', '1', '0,5', '0', '0,5', '1', '0,5', '0'],
            'U': ['1', '0,71', '0', '0,71', '1', '0,71', '0', '0,71', '1']}[key]


def _solve_lg(p):
    def prof(key):
        out = []
        for j in range(9):
            ph = 2 * math.pi * j / 8
            v = {'q': math.cos(ph), 'i': abs(math.sin(ph)), 'WC': math.cos(ph) ** 2, 'WL': math.sin(ph) ** 2, 'U': abs(math.cos(ph))}[key]
            out.append(round(v, 2))
        return out
    res = {}
    for L, tab in (('А', p['ta']), ('Б', p['tb'])):
        vals = [float(x.replace('−', '-').replace(',', '.')) for x in tab]
        hits = [rid for rid, key in p['right'].items() if all(abs(a - b) < 0.011 for a, b in zip(prof(key), vals))]
        res[L] = hits[0] if len(hits) == 1 else 'нет'
    return res


@proto('ph-ege-15-lc-graph', 'ЕГЭ', 15, 'Свободные колебания в контуре: какой величине соответствует зависимость от времени (таблица вместо графика)',
       invariant='конденсатор заряжен при t = 0: q ∝ cos ωt, i ∝ sin ωt, Wэл ∝ cos² ωt (период T/2), Wм ∝ sin² ωt',
       varies='сюжет (переключатель, ключ), шаг (T/8), какие две зависимости даны, набор величин справа',
       answer_rule='две цифры — номера величин для таблиц А и Б',
       mistakes=['энергия колеблется с периодом T (на самом деле T/2)', 'путают заряд и силу тока (сдвиг на T/4)'],
       solve=_solve_lg, kes=['3.5.1', '3.5.2'],
       fidelity=fid('две цифры', 'как демо 2027 №15 (графики А и Б → величины); график заменён таблицей значений в долях максимума',
                    'Б', 4, 'значения в моменты 0…T с шагом T/8', 'период энергии T/2, сдвиг фаз тока и заряда', ['3.5.1', '3.5.2'], SC_MATCH))
def g15_lg(rng):
    keys = list(LG_SHAPES)
    rng.shuffle(keys)
    if 'q' in keys[:4] and 'U' in keys[:4]:
        right = [k for k in keys if k != rng.choice(['q', 'U'])][:4]
    else:
        right = keys[:4]
    A, B = rng.sample(right, 2)
    ta, tb = _lg_values(A), _lg_values(B)
    moments = ['0', 'T/8', 'T/4', '3T/8', 'T/2', '5T/8', '3T/4', '7T/8', 'T']
    tA = '; '.join(f'{m}: {v}' for m, v in zip(moments, ta))
    tB = '; '.join(f'{m}: {v}' for m, v in zip(moments, tb))
    plot = rng.choice(['Конденсатор идеального колебательного контура зарядили от батареи и в момент t = 0 замкнули на катушку.',
                       'Переключатель, соединявший конденсатор идеального контура с источником постоянного напряжения, в момент t = 0 перевели в положение, при котором конденсатор замкнут на катушку.',
                       'В момент t = 0 заряженный конденсатор подключили к катушке индуктивности; контур можно считать идеальным.'])
    q = (f'{plot} Таблицы А и Б показывают, как меняются со временем две величины, характеризующие возникшие колебания '
         f'(значения даны в долях максимального; T — период колебаний). А) {tA}. Б) {tB}. '
         f'Установите соответствие между таблицами и физическими величинами, зависимость которых от времени они могут отражать.{TAIL}')
    rids = '1234'
    o = match_opts(['таблица А', 'таблица Б'], [LG_SHAPES[k] for k in right])
    ans = {'А': rids[right.index(A)], 'Б': rids[right.index(B)]}
    e = f'При t = 0 конденсатор заряжен: q ∝ cos(2πt/T), |i| ∝ |sin(2πt/T)|, энергии ∝ cos² и sin². А — {LG_SHAPES[A]}, Б — {LG_SHAPES[B]}. Ответ: {ans["А"]}{ans["Б"]}.'
    return pcard('ph-ege-15-lc-graph', q, ans, e, k='match', o=o, p={'ta': ta, 'tb': tb, 'right': {rids[i]: k for i, k in enumerate(right)}})


