def unit_t(n, u):
    """Время с единицей: «24 года», «5 лет», «12 ч», «8 сут»."""
    if u != 'лет':
        return f'{ru(n)} {u}'
    n = Fr(n)
    if n.denominator != 1:
        return f'{ru(n)} года'
    k = n.numerator
    w = 'год' if k % 10 == 1 and k % 100 != 11 else ('года' if k % 10 in (2, 3, 4) and k % 100 not in (12, 13, 14) else 'лет')
    return f'{k} {w}'


SUPD = str.maketrans('0123456789', '⁰¹²³⁴⁵⁶⁷⁸⁹')
SUBD = str.maketrans('0123456789', '₀₁₂₃₄₅₆₇₈₉')


def nuc(a, z):
    """Запись ядра как в КИМ: ²³⁸₉₂U."""
    return f'{str(a).translate(SUPD)}{str(z).translate(SUBD)}{EL[z][0]}'


