            (210, 81, 'β⁻'), (239, 93, 'β⁻'), (14, 6, 'β⁻'), (60, 27, 'β⁻'), (90, 38, 'β⁻'), (131, 53, 'β⁻'), (137, 55, 'β⁻'),
