             ((19, 9), 'p', (16, 8), 'α'), ((11, 5), 'p', (8, 4), 'α'), ((26, 12), 'd', (24, 11), 'α'), ((59, 27), 'n', (60, 27), 'γ'),
             ((9, 4), 'd', (10, 5), 'n'), ((12, 6), 'd', (13, 7), 'n'), ((11, 5), 'α', (14, 7), 'n'), ((7, 3), 'α', (10, 5), 'n'),
