def _solve_react(p):
    (a, z), pr, out, hide = p['tgt'], p['pr'], p['out'], p['hide']
    sa = a + PSH[pr][0] - PSH[out][0]
    sz = z + PSH[pr][1] - PSH[out][1]
    return str({'A': sa, 'Z': sz, 'N': sa - sz}[p['ask']])


@proto('ph-ege-16-reaction', 'ЕГЭ', 16, 'Ядерная реакция с лёгкой частицей: найти A, Z или N неизвестного ядра',
       invariant='сохранение суммарного массового числа и суммарного заряда в ядерной реакции',
       varies='реакция (мишень, налетающая и вылетающая частицы — n, p, d, α, γ), что спросить',
       answer_rule='целое число',
       mistakes=['не учитывают вылетевшую частицу', 'для нейтрона берут заряд 1', 'путают A и Z'],
       solve=_solve_react, kes=['4.3.4'],
       fidelity=fid('целое число', 'КИМ: реакция в символьной записи, «Каково массовое число ядра X?»', 'Б', 2,
                    'реальные реакции (Резерфорд, Чедвик, синтез)', 'сумма A и Z до и после', ['4.3.4'], SC_ONE))
def g16_react(rng):
    tgt, pr, prod, out = rng.choice(REACTIONS)
    a, z = tgt
    if z not in EL or prod[1] not in EL:
        raise Retry
    if a + PSH[pr][0] != prod[0] + PSH[out][0] or z + PSH[pr][1] != prod[1] + PSH[out][1]:
        raise Retry
    ask = rng.choice(['A', 'Z', 'Z', 'A', 'N'])
    eqn = f'{nuc(a, z)} + {PSYM[pr]} → X + {PSYM[out]}'
    askt = {'A': 'массовое число', 'Z': 'зарядовое число', 'N': 'число нейтронов в ядре'}[ask]
    q = rng.choice([f'В ядерной реакции {eqn} образуется ядро X. Каково {askt} ядра X? Ответ: ___.',
                    f'При облучении ядер {EL[z][1]} идёт реакция {eqn}. Определите {askt} {"ядра " if ask != "N" else ""}X. Ответ: ___.'])
    sa, sz = prod
    ans = str({'A': sa, 'Z': sz, 'N': sa - sz}[ask])
    e = f'Сохраняются A и Z: A = {a} + {PSH[pr][0]} − {PSH[out][0]} = {sa}, Z = {z} + {PSH[pr][1]} − {PSH[out][1]} = {sz}; X — {nuc(sa, sz)}.'
    wrong = [str(a + PSH[pr][0]), str(z + PSH[pr][1]), str(sz if ask != 'Z' else sa), str(a), str(z)]
    return pcard('ph-ege-16-reaction', q, ans, e, p={'tgt': [a, z], 'pr': pr, 'out': out, 'hide': 'X', 'ask': ask}, wrong=wrong,
                 nuc=((a + PSH[pr][0], z + PSH[pr][1]), (sa + PSH[out][0], sz + PSH[out][1])))


