def _solve_fis(p):
    (A, Z), (a1, z1), known, k = p['par'], p['x'], p['y'], p['k']
    if p['ask'] == 'k':
        return str(A + 1 - a1 - known[0])
    return str({'A': A + 1 - known[0] - k, 'Z': Z - known[1]}[p['ask']])


@proto('ph-ege-16-fission', 'ЕГЭ', 16, 'Деление урана/плутония нейтроном: найти A или Z осколка, число нейтронов',
       invariant='n + ядро → X + Y + k·n; сохраняются суммарные A и Z (нейтрон: A = 1, Z = 0)',
       varies='делящееся ядро (²³⁵U, ²³⁹Pu), пара осколков, число вторичных нейтронов, что спросить',
       answer_rule='целое число',
       mistakes=['забывают налетающий нейтрон', 'не умножают на число вылетевших нейтронов'],
       solve=_solve_fis, kes=['4.3.4', '4.3.5'],
       fidelity=fid('целое число', 'КИМ: «В результате реакции деления ¹n + ²³⁵U → X + ¹⁴⁵Cs + 3n образуется ядро X…»', 'Б', 2,
                    'реальные каналы деления', 'учёт налетающего и вторичных нейтронов', ['4.3.4'], SC_ONE))
def g16_fis(rng):
    par, x, y, k = rng.choice(FISSION)
    if rng.random() < 0.5:
        x, y = y, x
    ask = rng.choice(['A', 'Z', 'k'])
    A, Z = par
    if ask == 'k':
        eqn = f'¹₀n + {nuc(A, Z)} → {nuc(*x)} + {nuc(*y)} + k·¹₀n'
        q = f'Одна из возможных реакций деления: {eqn}. Сколько нейтронов (k) выделяется в этой реакции? Ответ: ___.'
        ans = str(k)
    else:
        eqn = f'¹₀n + {nuc(A, Z)} → X + {nuc(*y)} + {k}·¹₀n'
        q = rng.choice([f'При делении ядра {EL[Z][1]} нейтроном идёт реакция {eqn}. Каково {"массовое" if ask == "A" else "зарядовое"} число осколка X? Ответ: ___.',
                        f'В ядерном реакторе происходит реакция {eqn}. Определите {"массовое" if ask == "A" else "зарядовое"} число ядра X. Ответ: ___.'])
        ans = str(x[0] if ask == 'A' else x[1])
    e = f'Баланс: A: 1 + {A} = {x[0]} + {y[0]} + {k}; Z: {Z} = {x[1]} + {y[1]}. X — {nuc(*x)}.'
    wrong = [str(A - y[0]), str(A + 1 - y[0]), str(Z + 1 - y[1]), str(k + 1), str(x[0] + k)]
    return pcard('ph-ege-16-fission', q, ans, e, p={'par': list(par), 'x': list(x), 'y': list(y), 'k': k, 'ask': ask}, wrong=wrong,
                 nuc=((A + 1, Z), (x[0] + y[0] + k, x[1] + y[1])))


CHAINS = [((238, 92), (206, 82)), ((235, 92), (207, 82)), ((232, 90), (208, 82)), ((226, 88), (206, 82)), ((222, 86), (210, 82)),
          ((237, 93), (209, 83)), ((230, 90), (206, 82)), ((241, 94), (209, 83)), ((234, 92), (206, 82)), ((228, 90), (208, 82))]
