def _solve_chain(p):
    (A0, Z0), (A1, Z1) = p['a'], p['b']
    if p['ask'] == 'na':
        return str((A0 - A1) // 4)
    if p['ask'] == 'nb':
        return str(Z1 - (Z0 - 2 * ((A0 - A1) // 4)))
    na, nb = p['na'], p['nb']
    return str({'A': A0 - 4 * na, 'Z': Z0 - 2 * na + nb}[p['ask']])


@proto('ph-ege-16-chain', 'ЕГЭ', 16, 'Цепочка распадов: число α- и β-распадов или A, Z конечного ядра',
       invariant='каждый α-распад: A − 4, Z − 2; β⁻-распад: A не меняется, Z + 1; число α — по ΔA, β — по балансу Z',
       varies='радиоактивный ряд (U-238, U-235, Th-232, Ra-226, Np-237…), что спросить, число распадов',
       answer_rule='целое число',
       mistakes=['число β-распадов считают как ΔZ без учёта α', 'при β-распаде уменьшают Z'],
       solve=_solve_chain, kes=['4.3.2'],
       fidelity=fid('целое число', 'КИМ: «Сколько α-распадов испытывает ядро … при превращении в …»', 'Б', 2,
                    'реальные радиоактивные ряды', 'сначала α по A, затем β по Z', ['4.3.2'], SC_ONE))
def g16_chain(rng):
    a, b = rng.choice(CHAINS)
    ask = rng.choice(['na', 'nb', 'A', 'Z'])
    A0, Z0 = a
    na = (A0 - b[0]) // 4
    nb = b[1] - (Z0 - 2 * na)
    if ask in ('na', 'nb'):
        q = (f'Ядро {EL[Z0][1]} {nuc(A0, Z0)} в результате цепочки α- и β⁻-распадов превращается в стабильное ядро {nuc(*b)}. '
             f'Сколько {"α" if ask == "na" else "β⁻"}-распадов происходит в этой цепочке? Ответ: ___.')
        ans = str(na if ask == 'na' else nb)
        e = f'ΔA = {A0} − {b[0]} = {A0 - b[0]} → α-распадов {na}; Z после них {Z0 - 2 * na}, до {b[1]} нужно β⁻-распадов {nb}.'
        wrong = [str(nb if ask == 'na' else na), str(Z0 - b[1]), str(A0 - b[0]), str(na * 2)]
        p = {'a': list(a), 'b': list(b), 'ask': ask, 'na': na, 'nb': nb}
    else:
        na = rng.randint(1, 4)
        nb = rng.randint(0, 4)
        A1, Z1 = A0 - 4 * na, Z0 - 2 * na + nb
        bw = {0: 'электронных β-распадов', 1: 'электронный β-распад', 2: 'электронных β-распада', 3: 'электронных β-распада', 4: 'электронных β-распада'}[nb]
        q = (f'Ядро {nuc(A0, Z0)} испытало {na} α-распад{"а" if na in (2, 3, 4) else ""} и {nb} {bw}. '
             f'Каково {"массовое" if ask == "A" else "зарядовое"} число образовавшегося ядра? Ответ: ___.')
        ans = str(A1 if ask == 'A' else Z1)
        e = f'A = {A0} − 4·{na} = {A1}; Z = {Z0} − 2·{na} + {nb} = {Z1}.'
        wrong = [str(A0 - 2 * na), str(Z0 - 2 * na - nb), str(A1 - 4 * nb), str(Z0 - na + nb)]
        p = {'a': list(a), 'b': list(b), 'ask': ask, 'na': na, 'nb': nb}
    return pcard('ph-ege-16-chain', q, ans, e, p=p, wrong=wrong)


HL_ISO = [(28, 12, 21, 'ч'), (42, 19, 12, 'ч'), (131, 53, 8, 'сут'), (137, 55, 30, 'лет'), (90, 38, 29, 'лет'), (60, 27, 5, 'лет'),
          (222, 86, 4, 'сут'), (210, 84, 138, 'сут'), (32, 15, 14, 'сут'), (24, 11, 15, 'ч'), (99, 43, 6, 'ч'), (198, 79, 3, 'сут'),
          (144, 58, 285, 'сут'), (156, 63, 15, 'сут'), (35, 16, 87, 'сут'), (3, 1, 12, 'лет'), (228, 88, 6, 'лет'), (212, 82, 11, 'ч')]
