def _solve_dc(p):
    A, Z = 100, 40
    dA, dZ = p['d']
    A1, Z1 = A + dA, Z + dZ
    a = {'A': A, 'Z': Z, 'N': A - Z, 'nuc': A, 'el': Z}
    b = {'A': A1, 'Z': Z1, 'N': A1 - Z1, 'nuc': A1, 'el': Z1}
    return {'А': chg(a[p['A']], b[p['A']]), 'Б': chg(a[p['B']], b[p['B']])}


@proto('ph-ege-17-decay-change', 'ЕГЭ', 17, 'Радиоактивные превращения: как изменятся массовое число, заряд, число нейтронов ядра',
       invariant='α: A − 4, Z − 2; β⁻: n → p + e; β⁺ и K-захват: p → n; γ: A и Z не меняются; N = A − Z',
       varies='вид превращения (α, β⁻, β⁺, γ, захват n/p/e), конкретный изотоп в сюжете, пара величин',
       answer_rule='две цифры 1/2/3 по буквам А, Б',
       mistakes=['при β⁻-распаде уменьшают заряд', 'при α-распаде число нейтронов не меняют'],
       solve=_solve_dc, kes=['4.3.1', '4.3.2'],
       fidelity=fid('две цифры 1/2/3', 'КИМ: «Как изменятся при β⁻-распаде массовое число ядра и его заряд?»', 'Б', 3,
                    'реальные изотопы в условии', 'изменение N при β-распадах', ['4.3.1', '4.3.2'], SC_MATCH))
def g17_dc(rng):
    kind = rng.choice(list(DC_SIT))
    txt, d = DC_SIT[kind]
    cand = {'α': [x for x in NUCLIDES if x[2] == 'α'], 'β⁻': [x for x in NUCLIDES if x[2] == 'β⁻'],
            'β⁺': [x for x in NUCLIDES if x[2] == 'β⁺']}.get(kind, NUCLIDES)
    Aa, Zz = rng.choice(DC_NUC[kind]) if kind in DC_NUC else rng.choice(cand)[:2]
    A, B = rng.sample(list(DC_Q), 2)
    dA, dZ = d
    rule = {'A': dA, 'nuc': dA, 'Z': dZ, 'el': dZ, 'N': dA - dZ}
    code = lambda x: '3' if x == 0 else ('1' if x > 0 else '2')
    ans = {'А': code(rule[A]), 'Б': code(rule[B])}
    q = f'Ядро изотопа {EL[Zz][1]} {nuc(Aa, Zz)} {txt}. Как изменятся при этом {DC_Q[A]} и {DC_Q[B]} ядра? {Q_CHANGE}'
    e = f'ΔA = {dA:+d}, ΔZ = {dZ:+d}, ΔN = {dA - dZ:+d}. Ответ: {ans["А"]}{ans["Б"]}.'
    return change_card('ph-ege-17-decay-change', q, [DC_Q[A], DC_Q[B]], ans, e, {'d': [dA, dZ], 'A': A, 'B': B})


def _solve_lv(p):
    E = [Fr(x) for x in p['E']]
    tr = p['tr']     # список (из, в)
    def en(t):
        return abs(E[t[0]] - E[t[1]])
    res = {}
    for L, (proc, ext) in (('А', p['qa']), ('Б', p['qb'])):
        cand = [t for t in tr if (E[t[1]] > E[t[0]]) == (proc == 'погл')]
        best = max(cand, key=en) if ext == 'maxE' else min(cand, key=en)
        res[L] = str(tr.index(best) + 1) if p['right'] == 'tr' else p['emap'][fr(en(best))]
    return res


LV_ASK = {('погл', 'maxE'): ['поглощение фотона наибольшей энергии', 'поглощение света наименьшей длины волны', 'поглощение света наибольшей частоты'],
          ('погл', 'minE'): ['поглощение фотона наименьшей энергии', 'поглощение света наибольшей длины волны', 'поглощение света наименьшей частоты'],
          ('исп', 'maxE'): ['испускание фотона наибольшей энергии', 'излучение света наименьшей длины волны', 'излучение света наибольшей частоты'],
          ('исп', 'minE'): ['испускание фотона наименьшей энергии', 'излучение света наибольшей длины волны', 'излучение света наименьшей частоты']}


@proto('ph-ege-17-levels', 'ЕГЭ', 17, 'Энергетические уровни атома: какой переход соответствует поглощению/испусканию фотона заданного свойства',
       invariant='hν = |Eₘ − Eₙ|; переход вверх — поглощение, вниз — испускание; большая энергия ↔ большая частота ↔ меньшая длина волны',
       varies='значения уровней (эВ), набор переходов, процессы в левом столбце (энергия/частота/длина волны), вид правого столбца',
       answer_rule='две цифры — номер перехода (или энергии фотона) для А и Б',
       mistakes=['путают поглощение и испускание', 'наибольшая длина волны ↔ наибольшая энергия'],
       solve=_solve_lv, kes=['4.2.2', '4.2.3'],
       fidelity=fid('две цифры', 'как демо 2027 №17: диаграмма уровней (здесь — значения Eₙ и список переходов)', 'Б', 4,
                    'уровни порядка −14…0 эВ, 4–5 переходов', 'λ ∝ 1/E', ['4.2.2', '4.2.3'], SC_MATCH))
def g17_lv(rng):
    n = rng.choice([4, 5])
    base = sorted(rng.sample([-136, -120, -104, -85, -68, -51, -40, -34, -24, -15, -9, -5], n))
    E = [Fr(x, 10) for x in base]
    pairs = [(i, j) for i in range(n) for j in range(n) if i != j]
    rng.shuffle(pairs)
    tr = []
    for t in pairs:
        en = abs(E[t[0]] - E[t[1]])
        if all(abs(E[s[0]] - E[s[1]]) != en for s in tr):
            tr.append(t)
        if len(tr) == 4:
            break
    ups = [t for t in tr if t[1] > t[0]]
    dns = [t for t in tr if t[1] < t[0]]
    if len(ups) < 2 or len(dns) < 1:
        raise Retry
    keys = [k for k in LV_ASK if (k[0] == 'погл' and len(ups) >= 2) or (k[0] == 'исп' and len(dns) >= 2)]
    ka, kb = rng.sample(keys, 2)
    right = rng.choice(['tr', 'en'])
    en = lambda t: abs(E[t[0]] - E[t[1]])
    lvl = ', '.join(f'E{i} = {ru(e)} эВ' for i, e in enumerate(E))
    trs = '; '.join(f'{k + 1}) E{t[0]} → E{t[1]}' for k, t in enumerate(tr))
    def pick(k):
        cand = [t for t in tr if (t[1] > t[0]) == (k[0] == 'погл')]
        return max(cand, key=en) if k[1] == 'maxE' else min(cand, key=en)
    ta, tb = pick(ka), pick(kb)
    la, lb = rng.choice(LV_ASK[ka]), rng.choice(LV_ASK[kb])
    p = {'E': [fr(x) for x in E], 'tr': [list(t) for t in tr], 'qa': list(ka), 'qb': list(kb), 'right': right}
    if right == 'tr':
        q = (f'Атом имеет следующие энергетические уровни: {lvl}. Рассматриваются переходы атома между уровнями: {trs}. '
             f'Установите соответствие между процессами и переходами атома, при которых они происходят.{TAIL}')
        rt = [f'переход {k + 1}' for k in range(4)]
        ans = {'А': str(tr.index(ta) + 1), 'Б': str(tr.index(tb) + 1)}
        p['tr'] = [list(t) for t in tr]
    else:
        ens = [en(t) for t in tr]
        q = (f'Атом имеет следующие энергетические уровни: {lvl}. Возможны переходы: {trs}. '
             f'Установите соответствие между процессами и энергией соответствующего фотона.{TAIL}')
        rt = [f'{ru(x)} эВ' for x in ens]
        ans = {'А': str(ens.index(en(ta)) + 1), 'Б': str(ens.index(en(tb)) + 1)}
        p['emap'] = {fr(x): str(i + 1) for i, x in enumerate(ens)}
    if ans['А'] == ans['Б'] and ka[0] != kb[0]:
        raise Retry
    o = match_opts([la, lb], rt)
    e = (f'Поглощение — переход на более высокий уровень, испускание — на более низкий; E = |Eₘ − Eₙ|, λ = hc/E. '
         f'А: E{ta[0]} → E{ta[1]} ({ru(en(ta))} эВ); Б: E{tb[0]} → E{tb[1]} ({ru(en(tb))} эВ). Ответ: {ans["А"]}{ans["Б"]}.')
    return pcard('ph-ege-17-levels', q, ans, e, k='match', o=o, p=p)


PHF_FORMS = {'E': ('hc/λ', 'h*c/l'), 'p': ('h/λ', 'h/l'), 'Ek': ('hc/λ − A', 'h*c/l - A'), 'Uz': ('(hc/λ − A)/e', '(h*c/l - A)/e'),
             'lk': ('hc/A', 'h*c/A'), 'nuk': ('A/h', 'A/h'), 'x1': ('hλ/c', 'h*l/c'), 'x2': ('A − hc/λ', 'A - h*c/l'),
             'x3': ('hc/λ + A', 'h*c/l + A'), 'x4': ('h/(λc)', 'h/(l*c)')}
PHF_REF = {'E': 'h*(c/l)', 'p': '(h*c/l)/c', 'Ek': '(h*(c/l)) - A', 'Uz': '((h*(c/l)) - A)/e', 'lk': 'c/(A/h)', 'nuk': 'A/h',
           'x1': '0', 'x2': '0', 'x3': '0', 'x4': '0'}
PHF_Q = [('энергия фотона падающего света', 'E'), ('импульс фотона падающего света', 'p'), ('максимальная кинетическая энергия фотоэлектронов', 'Ek'),
         ('запирающее напряжение', 'Uz'), ('красная граница фотоэффекта λкр', 'lk'), ('минимальная частота света, вызывающего фотоэффект', 'nuk')]


@proto('ph-ege-17-formula-photo', 'ЕГЭ', 17, 'Фотоэффект и фотоны: соответствие величин и формул (λ, A, h, c, e)',
       invariant='E = hc/λ, p = h/λ, Eк = hc/λ − A, eUз = Eк, λкр = hc/A, νкр = A/h',
       varies='сюжет (металл, фотоэлемент), пара величин, формулы-дистракторы',
       answer_rule='две цифры — номера формул для А и Б',
       mistakes=['p = hλ/c', 'Eк = A − hc/λ', 'λкр = A/(hc)'],
       solve=_solve_formula, kes=['4.1.2', '4.1.4'],
       fidelity=fid('две цифры', 'КИМ: «Установите соответствие между физическими величинами и формулами (λ — длина волны, A — работа выхода…)»',
                    'Б', 3, 'буквенные формулы', 'уравнение Эйнштейна', ['4.1.2', '4.1.4'], SC_MATCH))
def g17_phf(rng):
    who = rng.choice(['Металлическую пластину с работой выхода A освещают монохроматическим светом с длиной волны λ; наблюдается фотоэффект.',
                      'Катод фотоэлемента (работа выхода A) облучают светом с длиной волны λ, вызывающим фотоэффект.',
                      'На поверхность металла с работой выхода A падает излучение с длиной волны λ, выбивающее электроны.'])
    q = f'{who} h — постоянная Планка, c — скорость света, e — модуль заряда электрона. Установите соответствие между физическими величинами и формулами, по которым их можно рассчитать. К каждой позиции первого столбца подберите соответствующую позицию из второго столбца и запишите в таблицу выбранные цифры под соответствующими буквами.'
    env = _envs(rng, ['h', 'c', 'l', 'A', 'e'])
    for d in env:
        d['A'] = d['h'] * d['c'] / d['l'] / 2.3
    return formula_card('ph-ege-17-formula-photo', rng, q, PHF_Q, PHF_FORMS, PHF_REF, env)


def _classify(eqn):
    """eqn: {'l': [[A,Z],...], 'r': [[A,Z],...], 'proj': True/False} → тип превращения."""
    L, R = eqn['l'], eqn['r']
    if sum(a for a, z in L) != sum(a for a, z in R) or sum(z for a, z in L) != sum(z for a, z in R):
        return 'ошибка'
    if len(L) > 1:
        return 'реакция'
    light = [x for x in R if x[0] <= 4]
    if [4, 2] in R and len(R) == 2:
        return 'α'
    if [0, -1] in R:
        return 'β⁻'
    if [0, 1] in R:
        return 'β⁺'
    if [0, 0] in R:
        return 'γ'
    return '?'


def _solve_deq(p):
    kinds = [_classify(x) for x in p['eqs']]
    return {'А': str(kinds.index(p['ka']) + 1), 'Б': str(kinds.index(p['kb']) + 1)}


DEQ_NAME = {'α': 'альфа-распад', 'β⁻': 'электронный бета-распад', 'β⁺': 'позитронный бета-распад', 'реакция': 'ядерная реакция под действием частицы',
            'γ': 'испускание γ-кванта возбуждённым ядром'}


def _pstr(x):
    a, z = x
    if (a, z) == (4, 2):
        return '⁴₂He'
    if (a, z) == (0, -1):
        return '⁰₋₁e'
    if (a, z) == (0, 1):
        return '⁰₊₁e'
    if (a, z) == (1, 0):
        return '¹₀n'
    if (a, z) == (1, 1):
        return '¹₁p'
    if (a, z) == (2, 1):
        return '²₁H'
    if (a, z) == (0, 0):
        return 'γ'
    return nuc(a, z)


@proto('ph-ege-17-decay-equation', 'ЕГЭ', 17, 'Виды радиоактивного распада и ядерные реакции: соответствие вида и уравнения',
       invariant='α — вылет ⁴₂He; β⁻ — вылет ⁰₋₁e (Z + 1); β⁺ — ⁰₊₁e (Z − 1); реакция — есть налетающая частица',
       varies='реальные изотопы в уравнениях, какие два вида спрашивают, дистракторы',
       answer_rule='две цифры — номера уравнений для А и Б',
       mistakes=['β⁺ путают с β⁻', 'реакцию с вылетом α-частицы принимают за α-распад'],
       solve=_solve_deq, kes=['4.3.2', '4.3.4'],
       fidelity=fid('две цифры', 'КИМ: «Установите соответствие между видами радиоактивного распада и уравнениями»', 'Б', 3,
                    'реальные нуклиды', 'налетающая частица = реакция, а не распад', ['4.3.2', '4.3.4'], SC_MATCH))
def g17_deq(rng):
    kinds = rng.sample(['α', 'β⁻', 'β⁺', 'реакция', 'γ'], 4)
    eqs = []
    for k in kinds:
        if k in ('α', 'β⁻', 'β⁺'):
            A, Z, _ = rng.choice([x for x in NUCLIDES if x[2] == k])
            dA, dZ = {'α': (-4, -2), 'β⁻': (0, 1), 'β⁺': (0, -1)}[k]
            if Z + dZ not in EL:
                raise Retry
            part = {'α': [4, 2], 'β⁻': [0, -1], 'β⁺': [0, 1]}[k]
            eqs.append({'l': [[A, Z]], 'r': [[A + dA, Z + dZ], part]})
        elif k == 'γ':
            A, Z, _ = rng.choice(NUCLIDES)
            eqs.append({'l': [[A, Z]], 'r': [[A, Z], [0, 0]], 'star': True})
        else:
            tgt, pr, prod, out = rng.choice(REACTIONS)
            if prod[1] not in EL or tgt[1] not in EL or pr == 'γ' or out not in PSH or out == 'γ' and False:
                raise Retry
            if tgt[0] + PSH[pr][0] != prod[0] + PSH[out][0] or tgt[1] + PSH[pr][1] != prod[1] + PSH[out][1]:
                raise Retry
            eqs.append({'l': [list(tgt), list(PSH[pr])], 'r': [list(prod), list(PSH[out])]})
    def txt(eq):
        l = ' + '.join(_pstr(x) + ('*' if eq.get('star') else '') for x in eq['l'])
        return f'{l} → ' + ' + '.join(_pstr(x) for x in eq['r'])
    texts = [txt(x) for x in eqs]
    ka, kb = rng.sample(kinds, 2)
    ans = {'А': str(kinds.index(ka) + 1), 'Б': str(kinds.index(kb) + 1)}
    q = 'Установите соответствие между видами ядерных превращений и уравнениями, которые их описывают.' + TAIL
    o = match_opts([DEQ_NAME[ka], DEQ_NAME[kb]], texts)
    e = f'{cap1(DEQ_NAME[ka])}: {texts[kinds.index(ka)]}; {DEQ_NAME[kb]}: {texts[kinds.index(kb)]}. Ответ: {ans["А"]}{ans["Б"]}.'
    return pcard('ph-ege-17-decay-equation', q, ans, e, k='match', o=o, p={'eqs': eqs, 'ka': ka, 'kb': kb})


# ================================================================= 18. Все разделы: выбор верных утверждений

# зависимости: ключ → (раздел, величина Y, род Y, аргумент X (в дательном/творит. формах), показатель, условие, функция для solve)
