    pos = f'Стрелка остановилась на {ORD[j]} штрихе после отметки {ru(L)} {unit} (в сторону бо́льших значений).'
    return meter_card('ph-ege-19-electric-meter', rng, head, scale_txt, pos, unit, step, ndiv, L, j, rule, (dev, what))


