def _solve_eq(p):
    right = set(EQUIP_R[p['goal']])
    return sorted(k for k, v in p['opts'].items() if v in right)


EQUIP_R = {g: r for g, _, r, _ in EQUIP}


@proto('ph-ege-20-equipment', 'ЕГЭ', 20, 'Выбор оборудования для измерения величины (два предмета из пяти)',
       invariant='по расчётной формуле величины — какие прямые измерения нужны и какими приборами',
       varies='измеряемая величина (плотность, жёсткость, сопротивление, мощность, g, μ, D, n, c), дистракторы',
       answer_rule='две цифры — номера выбранного оборудования (порядок не важен)',
       mistakes=['выбирают прибор, не нужный для расчётной формулы'],
       solve=_solve_eq, kind='dict', kes=['1', '2', '3'],
       fidelity=dict(FID20, style='КИМ: «Необходимо собрать экспериментальную установку, с помощью которой можно определить… Какие два предмета…»',
                     scale='школьное оборудование', trap='лишний прибор', kes=['1.2', '1.3', '3.2.3', '3.6.6']))
def g20_eq(rng):
    goal, base, right, distr = rng.choice(EQUIP)
    items = right + rng.sample(distr, 3)
    rng.shuffle(items)
    q = (f'Ученику нужно на опыте {goal}. У него уже есть {base}. Какие два предмета из перечня ниже ему следует добавить '
         f'к этому оборудованию, чтобы выполнить измерения? Запишите в ответ номера выбранных предметов.')
    ids = '12345'
    a = sorted(ids[items.index(x)] for x in right)
    e = f'Для этого, помимо взятого, нужны: {right[0]} и {right[1]}. Ответ: {"".join(a)}.'
    return pcard('ph-ege-20-equipment', q, a, e, k='many', o=opts(items), p={'goal': goal, 'opts': {ids[i]: t for i, t in enumerate(items)}},
                 extra={'answer_ege': ''.join(a)})


# ================================================================= 21. Качественная задача (с 2027 — только электродинамика)
# В КИМ ответ — развёрнутое объяснение (3 балла). Карточка проверяет первый шаг критериев — верный вывод
# (как изменятся показания / что произойдёт); полное объяснение с законами — в разборе e.

SC21 = '3 балла за верный вывод + полное объяснение с указанием законов; карточка проверяет вывод (шаг 1 критериев), объяснение — в разборе'
AF21 = 'в КИМ — развёрнутый ответ; здесь — вывод цифрами (как изменятся показания: 1/2/3) или выбором исхода; объяснение в разборе'
Q21 = 'Опираясь на законы электродинамики, объясните, как изменятся показания приборов.'

# ---- второй шаг задания 21: звенья объяснения (выбор из перечня / порядок). Цепочки строятся из параметров ситуации.

Q21_LINKS = ('Из приведённого ниже перечня выберите все утверждения, которые являются верными звеньями полного объяснения. '
             'Запишите цифры, под которыми они указаны.')
Q21_ORDER = 'Ниже в произвольном порядке приведены звенья объяснения. Расположите их в логической последовательности и запишите цифры в нужном порядке.'


def _dirw(up, g='m'):
    """«увеличивается/уменьшается» с родом не нужен — глаголы одинаковы."""
    return 'увеличивается' if up else 'уменьшается'


def chain_card(pid, rng, q, chain, p, e_concl):
    tl, fl = chain
    step = rng.choice(['links', 'order']) if len(tl) >= 3 else 'links'
    if step == 'links':
        k = min(rng.choice([2, 3]), len(tl))
        if len(fl) < 5 - k:
            raise Retry
        ch = [(t, True) for t in rng.sample(tl, k)] + [(t, False) for t in rng.sample(fl, 5 - k)]
        rng.shuffle(ch)
        texts = [t for t, _ in ch]
        a = [str(i + 1) for i, (_, ok) in enumerate(ch) if ok]
        e = ('Верные звенья: ' + '; '.join(f'{i + 1}) {t}' for i, (t, ok) in enumerate(ch) if ok) + '. Неверные: ' +
             ', '.join(str(i + 1) for i, (_, ok) in enumerate(ch) if not ok) + f'. {e_concl} Ответ: {"".join(a)}.')
        return pcard(pid, f'{q} {Q21_LINKS}', a, e, k='many', o=opts(texts), p=dict(p, step='links', sel=texts))
    links = tl[:4]
    perm = links[:]
    for _ in range(20):
        rng.shuffle(perm)
        if perm != links:
            break
    ans = ''.join(str(perm.index(t) + 1) for t in links)
    listing = ' '.join(f'{i + 1}) {t}' for i, t in enumerate(perm))
    import itertools
    others = [''.join(x) for x in itertools.permutations(ans) if ''.join(x) != ans]
    wrong = rng.sample(others, min(3, len(others)))
    e = 'Логическая цепочка: ' + ' → '.join(links) + f' Ответ: {ans}.'
    return pcard(pid, f'{q} {Q21_ORDER} {listing}', ans, e, k='num', p=dict(p, step='order', perm=perm), wrong=wrong)


def chain_solve(chain_fn, p):
    tl, fl = chain_fn(p)
    if p['step'] == 'links':
        return [str(i + 1) for i, t in enumerate(p['sel']) if t in tl]
    order = [t for t in tl if t in p['perm']]
    return ''.join(str(p['perm'].index(t) + 1) for t in order)


def s21(base, chain_fn):
    def solve(p):
        if p.get('step') in ('links', 'order'):
            return chain_solve(chain_fn, p)
        return base(p)
    return solve


def maybe_chain(pid, rng, q, chain_fn, p, e_concl, concl):
    if rng.random() < 2 / 3:
        return chain_card(pid, rng, q, chain_fn(p), p, e_concl)
    return concl()


