    fl = ['Предельный угол полного отражения увеличивается с ростом показателя преломления.', 'Радиус светлого круга не зависит от глубины источника.',
          'Полное внутреннее отражение возникает при переходе света из воздуха в жидкость.', 'Синус предельного угла равен показателю преломления жидкости.']
    return tl, fl


