def _solve_21d(p):
    E, r = Fr(12), Fr(1)
    R1, R2 = Fr(2), Fr(5)
    Ra, Rb = (R1, R2) if p['first'] == 'R1' else (R2, R1)
    def st(branch):
        R = Ra if branch == 1 else Rb
        I = E / (R + r)
        return {'Aall': I, 'A1': I if branch == 1 else Fr(0), 'Vsrc': E - I * r, 'V1': I * Ra if branch == 1 else Fr(0)}
    a, b = st(1), st(2)
    return {'А': chg(a[p['Am']], b[p['Am']]), 'Б': chg(a[p['V']], b[p['V']])}


