def _solve_21cur(p):
    I = [p['I1'], p['I2'], p['I3']]
    d = [0, p['d12'], p['d12'] + p['d23']]
    F = 0.0
    for j in (0, 2):
        same = (I[j] > 0) == (I[1] > 0)
        f = abs(I[j]) / abs(d[j] - d[1])
        sgn = (1 if j == 2 else -1) * (1 if same else -1)
        F += sgn * f
    res = 'нуль' if abs(F) < 1e-12 else ('к 3' if F > 0 else 'к 1')
    return [k for k, v in p['opts'].items() if v == CUR_OPTS[res]][0]


def kx(n, sym):
    return sym if n == 1 else f'{n}{sym}'


CUR_OPTS = {'к 1': 'к проводнику 1', 'к 3': 'к проводнику 3', 'нуль': 'равнодействующая сил равна нулю'}


@proto('ph-ege-21-currents', 'ЕГЭ', 21, 'Три параллельных проводника с токами: куда направлена сила на средний проводник',
       invariant='параллельные токи одного направления притягиваются, противоположного — отталкиваются; сила ∝ I₁I₂/r',
       varies='силы и направления токов, расстояния между проводниками',
       answer_rule='номер верного направления равнодействующей',
       mistakes=['одинаково направленные токи отталкиваются', 'не учитывают расстояние/силу тока'],
       solve=s21(_solve_21cur, _ch21cur), kes=['3.3.2', '3.3.3'],
       fidelity=dict(answer_format=AF21, style='КИМ №21: «Три параллельных длинных прямых проводника… Куда направлена сила…? Ответ поясните»',
                     level='П', time_min=8, scale='токи 1–4 А, расстояния одинаковые или кратные', trap='притяжение одинаково направленных токов',
                     kes=['3.3.2', '3.3.3'], score=SC21))
def g21_cur(rng):
    I1, I2, I3 = [rng.choice([1, 2, 3, 4]) * rng.choice([1, -1]) for _ in range(3)]
    d12, d23 = rng.choice([(1, 1), (1, 2), (2, 1), (1, 1)])
    items = list(CUR_OPTS.values())
    rng.shuffle(items)
    ids = '123'
    o = [{'id': ids[i], 't': t} for i, t in enumerate(items)]
    dirn = lambda x: 'вверх' if x > 0 else 'вниз'
    q = (f'Три длинных прямых параллельных проводника 1, 2, 3 лежат в одной плоскости; проводник 2 находится между 1 и 3, '
         f'расстояние от 2 до 1 равно {kx(d12, "a")}, от 2 до 3 — {kx(d23, "a")}. По проводникам текут токи {kx(abs(I1), "I")} ({dirn(I1)}), '
         f'{kx(abs(I2), "I")} ({dirn(I2)}) и {kx(abs(I3), "I")} ({dirn(I3)}) соответственно. Куда направлена равнодействующая сил Ампера, действующих на проводник 2 со стороны '
         f'проводников 1 и 3? Ответ поясните, указав, какие физические закономерности вы использовали.')
    p = {'I1': I1, 'I2': I2, 'I3': I3, 'd12': d12, 'd23': d23, 'opts': {x['id']: x['t'] for x in o}}
    # генератор: сравнение модулей сил и направлений
    f1 = Fr(abs(I1), d12)
    f3 = Fr(abs(I3), d23)
    v1 = -f1 if (I1 > 0) == (I2 > 0) else f1      # к 1 = отрицательное
    v3 = f3 if (I3 > 0) == (I2 > 0) else -f3
    tot = v1 + v3
    res = 'нуль' if tot == 0 else ('к 3' if tot > 0 else 'к 1')
    a = ids[items.index(CUR_OPTS[res])]
    e = (f'Одинаково направленные токи притягиваются, противоположно — отталкиваются; модуль силы ∝ I₁I₂/r. Со стороны 1: '
         f'{"притяжение" if (I1 > 0) == (I2 > 0) else "отталкивание"} ∝ {ru(f1)}, со стороны 3: '
         f'{"притяжение" if (I3 > 0) == (I2 > 0) else "отталкивание"} ∝ {ru(f3)}. Итог: {CUR_OPTS[res]}.')
    _p = p
    return maybe_chain('ph-ege-21-currents', rng, q, _ch21cur, _p, e,
                       lambda: pcard('ph-ege-21-currents', q, a, e, k='one', o=o, p=_p))


