        e = f'mg = ρ₁g·xV + ρ₂g(1 − x)V ⇒ ρ = xρ₁ + (1 − x)ρ₂ = {ru(x)}·{lo[1]} + {ru(1 - x)}·{hi[1]} ≈ {{ANS}} кг/м³.'
        wrong = [float(x * lo[1]), float((1 - x) * lo[1] + x * hi[1]), (lo[1] + hi[1]) / 2]
