    if u == 0 or Q <= 0:
        raise Retry
    Qunit, Qk = ('мДж', 1000) if Q < 1 else (('кДж', Fr(1, 1000)) if Q > 5000 else ('Дж', 1))
    val = float(abs(u)) if ask == 'u' else float(Q * Qk)
