       invariant='внутренняя энергия сохраняется: 3/2·R(ν₁T₁ + ν₂T₂) = 3/2·R(ν₁ + ν₂)T; p = (ν₁ + ν₂)RT/(V₁ + V₂)',
       varies='газ, количества вещества, температуры, объёмы, что найти (T или p)',
       answer_rule='T в К или p в кПа с указанным округлением',
