    r = rng.choice([0.5, 1, 1.5, 2, 3, 4, 5])
    R1, R2 = rng.choice([2, 3, 4, 5, 6, 8, 10, 12, 15, 20]), rng.choice([2, 3, 4, 5, 6, 8, 10, 12, 15, 20])
    C = rng.choice([1, 2, 4, 5, 10, 20, 50, 100])
    where = rng.choice(['R1', 'R2', 'src'])
    ask = rng.choice(['q', 'q', 'W'])
    I = E / (r + R1 + R2)
