    val = C * U if ask == 'q' else C * U * U / 2
    wt = {'R1': 'параллельно резистору R₁', 'R2': 'параллельно резистору R₂', 'src': 'к полюсам источника'}[where]
    q = (f'Источник с ЭДС {ru(Fr(E).limit_denominator(10))} В и внутренним сопротивлением {ru(Fr(r).limit_denominator(10))} Ом замкнут на последовательно соединённые '
         f'резисторы R₁ = {R1} Ом и R₂ = {R2} Ом. Конденсатор ёмкостью {C} мкФ подключён {wt}. ' +
         ('Каков заряд конденсатора (в мкКл) после установления тока?' if ask == 'q' else 'Какова энергия электрического поля конденсатора (в мкДж) после установления тока?') +
         f' {rq(1)}')
