    if ask == 'E':
        tg = rng.choice([Fr(1, 4), Fr(1, 2), Fr(3, 4), Fr(1), Fr(4, 3)])
        E = 0
        val = m / 1000 * 10 * float(tg) / (qn * 1e-9) / 1000
    else:
        E = rng.choice([1e4, 2e4, 5e4, 1e5, 2e5, 5e5, 1e6])
