# ---------- 14-ampere: проводник с током в магнитном поле (направление и модуль силы Ампера)

AX = {'x': (1, 0, 0), '-x': (-1, 0, 0), 'y': (0, 1, 0), '-y': (0, -1, 0), 'z': (0, 0, 1), '-z': (0, 0, -1)}
AX_TXT = {'x': 'вдоль оси Ox', '-x': 'противоположно оси Ox', 'y': 'вдоль оси Oy', '-y': 'противоположно оси Oy',
          'z': 'вертикально вверх (вдоль оси Oz)', '-z': 'вертикально вниз (противоположно оси Oz)'}


def _cross(a, b):
    return (a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0])


def _amp_model(p):
    I, B, l = Fr(p['I']), Fr(p['B']), Fr(p['l'], 100)
    d = _cross(AX[p['cur']], AX[p['fld']])
    name = [k for k, v in AX.items() if v == d]
    d2 = _cross(tuple(-x for x in AX[p['cur']]), AX[p['fld']])
    name2 = [k for k, v in AX.items() if v == d2]
    return {'F': I * B * l * 1000, 'dir': name[0] if name else '0', 'rev': name2[0] if name2 else '0', 'par': Fr(0),
            'F2I': Fr(2), 'Fl': Fr(1)}


@proto('ph-ege-14-ampere', 'ЕГЭ', 14, 'Проводник с током в однородном магнитном поле: модуль и направление силы Ампера (выбор верных)',
       invariant='FA = BIl·sin α; направление — по правилу левой руки (F ∝ I·l × B); при токе вдоль линий индукции F = 0',
       varies='сюжет (проводник на нитях между полюсами, стержень на рельсах), оси тока и поля, I, B, l, утверждения',
       answer_rule='номера верных утверждений',
       mistakes=['правило правой руки вместо левой', 'длина в см не переведена в м', 'сила «вдоль линий индукции»'],
       solve=solve_many(_amp_model), kes=['3.3.3'],
       fidelity=fid('последовательность 2–3 цифр', 'КИМ: «Проводник АБ подвешен… подключён к источнику… выберите все верные утверждения»; рисунок заменён осями координат',
                    'П', 5, 'l 5–50 см, I 1–10 А, B 0,05–1 Тл', 'направление силы Ампера', ['3.3.3'], SC_MANY))
def g14_amp(rng):
    cur = rng.choice(['x', '-x', 'y', '-y'])
    fld = rng.choice(['z', '-z']) if rng.random() < 0.6 else rng.choice([a for a in ('x', '-x', 'y', '-y') if a.strip('-') != cur.strip('-')])
    I = rng.choice([1, 2, 3, 4, 5, 6, 8, 10])
    B = Fr(rng.choice([5, 10, 20, 25, 40, 50, 80, 100]), 100)
    l = rng.choice([5, 10, 15, 20, 25, 30, 40, 50])
    F = I * B * Fr(l, 100) * 1000
    d = _cross(AX[cur], AX[fld])
    dname = [k for k, v in AX.items() if v == d][0]
    opp = dname[1:] if dname.startswith('-') else '-' + dname
    wrongdir = rng.choice([k for k in AX if k not in (dname,)])
    items = [
        (f'Модуль силы Ампера, действующей на проводник, равен {ru(F)} мН.', {'t': 'v', 'q': 'F', 'v': fr(F)}, True, f'F = BIl = {ru(F)} мН'),
        (f'Модуль силы Ампера, действующей на проводник, равен {ru(F * 100)} мН.', {'t': 'v', 'q': 'F', 'v': fr(F * 100)}, False, 'длину нужно выразить в метрах'),
        (f'Сила Ампера направлена {AX_TXT[dname]}.', {'t': 'is', 'q': 'dir', 'v': dname}, True, 'правило левой руки'),
        (f'Сила Ампера направлена {AX_TXT[wrongdir]}.', {'t': 'is', 'q': 'dir', 'v': wrongdir}, False, f'по правилу левой руки — {AX_TXT[dname]}'),
        (f'Если изменить направление тока на противоположное, сила Ампера будет направлена {AX_TXT[opp]}.', {'t': 'is', 'q': 'rev', 'v': opp}, True,
         'при смене направления тока сила меняет направление'),
        ('Если изменить направление тока на противоположное, направление силы Ампера не изменится.', {'t': 'is', 'q': 'rev', 'v': dname}, False,
         'сила меняет направление на противоположное'),
        ('Если силу тока увеличить в 2 раза, модуль силы Ампера увеличится в 2 раза.', {'t': 'r', 'q': 'F2I', 'v': '2'}, True, 'F ∝ I'),
        ('Модуль силы Ампера не зависит от длины проводника, находящегося в поле.', {'t': 'r', 'q': 'Fl', 'v': '0'}, False, 'F ∝ l'),
    ]
    plot = rng.choice(['Прямой горизонтальный проводник подвешен на тонких проводящих нитях между полюсами подковообразного магнита',
                       'Лёгкий металлический стержень лежит на двух проводящих рельсах, подключённых к источнику',
                       'Прямолинейный участок провода находится в однородном магнитном поле электромагнита'])
    q = (f'{plot}. Длина части проводника, находящейся в поле, {l} см, сила тока {I} А, индукция поля {ru(B)} Тл. '
         f'Ось Oz направлена вертикально вверх, оси Ox и Oy горизонтальны. Проводник расположен вдоль оси O{cur[-1]}, ток течёт {AX_TXT[cur]}; '
         f'вектор магнитной индукции направлен {AX_TXT[fld]}. {Q_MANY}')
    return many_card('ph-ege-14-ampere', rng, q, items, {'I': I, 'B': fr(B), 'l': l, 'cur': cur, 'fld': fld})


# ---------- 21-electrostatic: электризация через влияние (электрометр)

ES_SEQ = {
    'near_away': (['К шару незаряженного электрометра подносят, не касаясь, {s} заряженную палочку.', 'Затем палочку убирают.'], 0),
    'ground': (['К шару незаряженного электрометра подносят, не касаясь, {s} заряженную палочку.', 'Не убирая палочку, касаются шара пальцем.',
                'Затем убирают палец, а после этого — палочку.'], -1),
    'touch': (['{S} заряженной палочкой касаются шара незаряженного электрометра.', 'Затем палочку убирают.'], 1),
    'ground_wrong': (['К шару незаряженного электрометра подносят, не касаясь, {s} заряженную палочку.', 'Не убирая палочку, касаются шара пальцем.',
                      'Затем сначала убирают палочку, а потом — палец.'], 0),
    'two_far': (['Два незаряженных электрометра соединены металлическим стержнем. К шару первого электрометра подносят, не касаясь, {s} заряженную палочку.',
                 'Не убирая палочку, стержень убирают, держа его за изолирующую ручку.', 'Затем убирают палочку. Рассмотрите второй электрометр.'], 1),
    'two_near': (['Два незаряженных электрометра соединены металлическим стержнем. К шару первого электрометра подносят, не касаясь, {s} заряженную палочку.',
                  'Не убирая палочку, стержень убирают, держа его за изолирующую ручку.', 'Затем убирают палочку. Рассмотрите первый электрометр.'], -1),
}
ES_OPTS = {1: 'электрометр заряжен так же, как палочка (стрелка отклонена)', -1: 'электрометр заряжен противоположно палочке (стрелка отклонена)',
           0: 'электрометр не заряжен (стрелка не отклонена)'}


def _solve_es(p):
    """Мини-модель: знак заряда палочки s; заряд электрометра по шагам процедуры."""
    seq, s = p['seq'], p['s']
    if seq == 'touch':
        q = s
    elif seq in ('near_away', 'ground_wrong'):
        q = 0
    elif seq == 'ground':
        q = -s          # через палец уходит заряд того же знака, что у палочки
    elif seq == 'two_far':
        q = s           # дальний электрометр получает заряд знака палочки
    else:
        q = -s
    rel = 0 if q == 0 else (1 if q == s else -1)
    return [k for k, v in p['opts'].items() if v == ES_OPTS[rel]][0]


@proto('ph-ege-21-electrostatic', 'ЕГЭ', 21, 'Электризация через влияние: какой заряд окажется на электрометре после серии действий',
       invariant='электростатическая индукция: в проводнике заряды разделяются, суммарный заряд сохраняется; заземление (рука) отводит заряд',
       varies='знак заряда палочки, последовательность действий (поднесли/коснулись/заземлили/разделили два электрометра), какой электрометр',
       answer_rule='номер верного исхода',
       mistakes=['при поднесении без касания электрометр «заряжается»', 'после заземления заряд того же знака, что у палочки'],
       solve=s21(_solve_es, _ch21es), kes=['3.1.1', '3.1.7'],
       fidelity=dict(answer_format=AF21, style='КИМ №21: «На столе установили два незаряженных электрометра… Объясните…»', level='П', time_min=8,
                     scale='без чисел', trap='порядок: сначала убирают палец, потом палочку', kes=['3.1.1', '3.1.7'], score=SC21))
def g21_es(rng):
    seq = rng.choice([k for k in ES_SEQ if k != 'touch'])
    steps, rel = ES_SEQ[seq]
    s = rng.choice([1, -1])
    sign, Sign = ('положительно', 'Положительно') if s > 0 else ('отрицательно', 'Отрицательно')
    stick = rng.choice(['стеклянную палочку', 'эбонитовую палочку', 'палочку из оргстекла'])
    txt = ' '.join(steps).format(s=sign, S=Sign).replace('заряженную палочку', f'заряженную {stick}')
    items = list(ES_OPTS.values())
    rng.shuffle(items)
    ids = '123'
    o = [{'id': ids[i], 't': t} for i, t in enumerate(items)]
    a = ids[items.index(ES_OPTS[rel])]
    q = f'{txt} Каким окажется заряд электрометра в конце опыта? Ответ поясните, указав, какие физические явления и закономерности вы использовали.'
    why = {'near_away': 'при поднесении заряды в электрометре лишь перераспределяются (электростатическая индукция), суммарный заряд остаётся нулевым; после удаления палочки распределение восстанавливается',
           'ground': 'палочка притягивает к шару заряды противоположного знака, а заряды того же знака уходят через палец в землю; после удаления пальца (при палочке рядом) избыточный заряд противоположного знака остаётся',
           'touch': 'при касании часть заряда палочки переходит на электрометр',
           'ground_wrong': 'палочку убрали, пока палец касался шара, — избыточный заряд ушёл в землю, электрометр остался нейтральным',
           'two_far': 'заряды разделились: на ближнем электрометре — противоположного знака, на дальнем — того же знака, что у палочки; после разделения они сохраняются',
           'two_near': 'на ближнем к палочке электрометре собираются заряды противоположного знака; после разделения они сохраняются'}[seq]
    e = f'{cap1(why)}. Ответ: {ES_OPTS[rel]}.'
    _p = {'seq': seq, 's': s, 'opts': {x['id']: x['t'] for x in o}}
    return maybe_chain('ph-ege-21-electrostatic', rng, q, _ch21es, _p, e,
                       lambda: pcard('ph-ege-21-electrostatic', q, a, e, k='one', o=o, p=_p))


# ---------- 22-statics: линейка на краю стола / рычаг

def _s22st(p):
    if p['kind'] == 'ruler':
        M, L, a = p['M'], Fr(p['L']), Fr(p['a'])
        return fmt(float(M * (L / 2 - a) / a), p['dec'])
    M, d1, d2, m = p['M'], Fr(p['d1']), Fr(p['d2']), Fr(p['m'])
    # рычаг массы m (однородный, длина d1 + d2, опора между плечами), груз M на плече d1, сила на конце плеча d2
    L = d1 + d2
    arm_c = L / 2 - d1
    return fmt(float((M * G10 * d1 - m * G10 * arm_c) / d2), p['dec'])


@proto('ph-ege-22-statics', 'ЕГЭ', 22, 'Равновесие твёрдого тела: линейка на краю стола с грузиком, рычаг с грузом',
       invariant='правило моментов относительно оси (края стола/опоры); сила тяжести однородного тела приложена в его середине',
       varies='сюжет (линейка, доска, лом-рычаг), масса, длина, выступ/плечи, что найти (масса грузика, сила)',
       answer_rule='масса в г или сила в Н с указанным округлением',
       mistakes=['плечо силы тяжести линейки от её конца', 'забывают массу рычага'],
       solve=_s22st, kes=['1.3.1', '1.3.2'],
       fidelity=p2fid(22, 'КИМ: «Деревянная линейка длиной 60 см выдвинута за край стола на 1/4 часть своей длины…»', 'линейки 30–100 см, массы 10–200 г',
                      'плечо силы тяжести однородного тела', ['1.3.1', '1.3.2'], 8))
def g22_st(rng):
    if rng.random() < 0.5:
        L = rng.choice([30, 40, 50, 60, 80, 100])
        frac = rng.choice([Fr(1, 5), Fr(1, 4), Fr(1, 3), Fr(2, 5)])
        a = L * frac
        M = rng.choice([20, 30, 40, 50, 60, 80, 100, 150, 200])
        obj = rng.choice(['Деревянная линейка', 'Однородная планка', 'Лёгкая пластмассовая доска-указка'])
        val = float(M * (Fr(L, 2) - a) / a)
        q = (f'{obj} массой {M} г и длиной {L} см лежит на столе и выдвинута за его край на {ru(frac)} своей длины. Какой наибольшей массы грузик (в г) '
             f'можно положить на выступающий конец, чтобы она оставалась в равновесии? Сделайте рисунок с указанием сил. {rq(0)}')
        e = f'Ось — край стола. Момент грузика m·g·a уравновешен моментом силы тяжести линейки M·g·(L/2 − a): m = M(L/2 − a)/a = {sf(val)} г. Ответ: {{ANS}}.'
        wrong = [M * float(frac), float(M * (L - a) / a), float(M * (Fr(L, 2)) / a)]
        return num_card('ph-ege-22-statics', q, val, 0, e, {'kind': 'ruler', 'M': M, 'L': fr(L), 'a': fr(a)}, wrong)
    M = rng.choice([20, 30, 40, 50, 60, 75, 80, 100, 120])
    d1 = Fr(rng.choice([10, 15, 20, 25, 30]), 100)
    d2 = Fr(rng.choice([80, 100, 120, 150, 180]), 100)
    m = Fr(rng.choice([0, 0, 2, 3, 4, 5]))
    L = d1 + d2
    val = float((M * 10 * d1 - m * 10 * (L / 2 - d1)) / d2)
    if val <= 0:
        raise Retry
    lever = 'лёгкого лома' if m == 0 else f'однородного лома массой {m} кг'
    q = (f'Груз массой {M} кг поднимают с помощью {lever}, опирающегося на камень. Расстояние от груза до точки опоры {ru(d1 * 100)} см, от точки опоры до '
         f'места приложения силы (конец лома) {ru(d2 * 100)} см. Какую минимальную вертикальную силу (в Н) нужно приложить к концу лома, чтобы удерживать груз '
         f'в равновесии? Сделайте рисунок с указанием сил. {rq(1)}')
    e = (f'Правило моментов относительно опоры: Mg·d₁ = F·d₂' + ('' if m == 0 else f' + mg·(L/2 − d₁)') + f' ⇒ F ≈ {sf(val)} Н. Ответ: {{ANS}}.')
    wrong = [M * 10 * float(d2 / d1), M * 10, float(M * 10 * d1 / d2) if m else val * 2]
    return num_card('ph-ege-22-statics', q, val, 1, e, {'kind': 'lever', 'M': M, 'd1': fr(d1), 'd2': fr(d2), 'm': fr(m)}, wrong)


MAT = [('стальной', 7800), ('алюминиевый', 2700), ('медный', 8900), ('свинцовый', 11300), ('чугунный', 7000)]
WOOD = [('сосновый', 400), ('дубовый', 700), ('пробковый', 240), ('берёзовый', 650)]


def _s22bt(p):
    m, rb, rl = p['m'], p['rb'], p['rl']
    return fmt(abs(m * G10 * (1 - rl / rb)), p['dec'])


@proto('ph-ege-22-buoyancy-thread', 'ЕГЭ', 22, 'Тело на нити полностью погружено в жидкость: сила натяжения нити',
       invariant='T + FA = mg (тяжёлое тело) или T + mg = FA (лёгкое тело привязано ко дну); FA = ρж g m/ρт',
       varies='материал тела (металл/дерево), масса, жидкость, подвешено сверху или привязано ко дну',
       answer_rule='T в Н с указанным округлением',
       mistakes=['T = mg', 'знак силы Архимеда для лёгкого тела'],
       solve=_s22bt, kes=['1.3.6', '1.2.4'],
       fidelity=p2fid(22, 'КИМ: «Железный шар массой 2,5 кг подвешен на нити и полностью погружён в воду… / Деревянный шар привязан нитью ко дну…»',
                      'массы 0,1–5 кг, плотности из справочных таблиц КИМ', 'равновесие трёх сил', ['1.3.6'], 8))
def g22_bt(rng):
    liq = rng.choice(['вода', 'керосин', 'масло'])
    rl = LIQ[liq]
    if rng.random() < 0.6:
        mat, rb = rng.choice(MAT)
        form = rng.choice(['шар', 'цилиндр', 'брусок'])
        m = rng.choice([0.5, 1, 1.5, 2, 2.5, 3, 4, 5])
        q = (f'Сплошной {mat} {form} массой {ru(Fr(m).limit_denominator(10))} кг подвешен на нити и целиком погружён в {({"вода": "воду", "керосин": "керосин", "масло": "подсолнечное масло"})[liq]}, '
             f'не касаясь дна. Плотность материала {rb} кг/м³, жидкости {rl} кг/м³. Найдите силу натяжения нити (в Н). {rq(1)}')
        e = f'Равновесие: T + ρж g V = mg, V = m/ρ ⇒ T = mg(1 − ρж/ρ) ≈ {sf(m * 10 * (1 - rl / rb))} Н. Ответ: {{ANS}}.'
        wrong = [m * 10, m * 10 * rl / rb, m * 10 * (1 + rl / rb)]
    else:
        mat, rb = rng.choice(WOOD)
        m = rng.choice([0.2, 0.3, 0.4, 0.5, 0.8, 1, 1.2, 1.6])
        if rb >= rl:
            raise Retry
        q = (f'Сплошной {mat} шар массой {ru(Fr(m).limit_denominator(10))} кг привязан нитью ко дну сосуда с {({"вода": "водой", "керосин": "керосином", "масло": "маслом"})[liq]} '
             f'и целиком находится в жидкости. Плотность дерева {rb} кг/м³, жидкости {rl} кг/м³. Найдите силу натяжения нити (в Н). {rq(1)}')
        e = f'Равновесие: ρж g V = mg + T, V = m/ρ ⇒ T = mg(ρж/ρ − 1) ≈ {sf(m * 10 * (rl / rb - 1))} Н. Ответ: {{ANS}}.'
        wrong = [m * 10, m * 10 * rl / rb, m * 10 * (1 + rl / rb)]
    return num_card('ph-ege-22-buoyancy-thread', q, abs(m * 10 * (1 - rl / rb)), 1, e, {'m': m, 'rb': rb, 'rl': rl}, wrong)


# ---------- 23-mercury-tube: столбик ртути в трубке

def _s23mt(p):
    L1, h, p0 = Fr(p['L1']), Fr(p['h']), Fr(p['p0'])
    pa = {'up': p0 + h, 'down': p0 - h, 'hor': p0}
    return fmt(float(L1 * pa[p['from']] / pa[p['to']]), p['dec'])


@proto('ph-ege-23-mercury-tube', 'ЕГЭ', 23, 'Воздух в трубке, запертый столбиком ртути: длина столба воздуха после поворота трубки',
       invariant='T = const: p₁L₁ = p₂L₂; давление воздуха p₀ ± h (мм рт. ст.) в зависимости от положения трубки',
       varies='начальное и конечное положение (горизонтально, открытым концом вверх/вниз), длины, атмосферное давление',
       answer_rule='длина в см с указанным округлением',
       mistakes=['знак h при открытом конце вниз', 'давление в мм рт. ст. путают с длиной в см'],
       solve=_s23mt, kes=['2.1.12'],
       fidelity=p2fid(23, 'КИМ: «В запаянной с одного конца стеклянной трубке… воздух отделён от атмосферы столбиком ртути…»', 'h 50–200 мм, L 10–50 см, p₀ 740–770 мм рт. ст.',
                      'давление под ртутью в разных положениях', ['2.1.12'], 8))
def g23_mt(rng):
    L1 = rng.choice([10, 12, 15, 18, 20, 24, 25, 30, 40])
    h = rng.choice([50, 76, 100, 120, 150, 152, 190, 200])
    p0 = rng.choice([740, 750, 760, 770])
    fr_, to = rng.sample(['up', 'down', 'hor'], 2)
    pa = {'up': p0 + h, 'down': p0 - h, 'hor': p0}
    val = L1 * pa[fr_] / pa[to]
    pos = {'up': 'вертикально открытым концом вверх', 'down': 'вертикально открытым концом вниз', 'hor': 'горизонтально'}
    q = (f'В тонкой стеклянной трубке, запаянной с одного конца, находится столбик воздуха, отделённый от атмосферы столбиком ртути длиной {h} мм. '
         f'Когда трубка расположена {pos[fr_]}, длина столбика воздуха {L1} см. Какой станет длина столбика воздуха (в см), если трубку медленно '
         f'расположить {pos[to]}? Атмосферное давление {p0} мм рт. ст., температура постоянна. {rq(1)}')
    e = (f'Давление воздуха: открытым концом вверх p₀ + h, вниз p₀ − h, горизонтально p₀ (мм рт. ст.). Закон Бойля–Мариотта: p₁L₁ = p₂L₂ ⇒ '
         f'L₂ = {L1}·{pa[fr_]}/{pa[to]} ≈ {sf(val)} см. Ответ: {{ANS}}.')
    wrong = [L1 * pa[to] / pa[fr_], L1 * p0 / pa[to], L1 + h / 10]
    return num_card('ph-ege-23-mercury-tube', q, val, 1, e, {'L1': L1, 'h': h, 'p0': p0, 'from': fr_, 'to': to}, wrong)


# ---------- 25-circuit-power: мощности в цепи с источником

def _s25cp(p):
    E, r, R1, R2 = [Fr(p[k]) for k in ('E', 'r', 'R1', 'R2')]
    if p['ask'] == 'Pmax':
        return fmt(float(E * E / (4 * r)), p['dec'])
    if p['par']:
        Rp = R1 * R2 / (R1 + R2)
        I = E / (Rp + r)
        U = I * Rp
        P2 = U * U / R2
    else:
        I = E / (R1 + R2 + r)
        P2 = I * I * R2
        U = I * (R1 + R2)
    return fmt(float({'P2': P2, 'eta': U / E * 100}[p['ask']]), p['dec'])


@proto('ph-ege-25-circuit-power', 'ЕГЭ', 25, 'Цепь с источником (ℰ, r) и двумя резисторами: мощность на резисторе, КПД, максимальная полезная мощность',
       invariant='закон Ома для полной цепи; P = I²R = U²/R; η = U/ℰ; Pmax при R = r: ℰ²/(4r)',
       varies='ЭДС и r источника (аккумулятор, батарея), R₁, R₂, соединение, что найти',
       answer_rule='мощность в Вт или КПД в % с указанным округлением',
       mistakes=['не учитывают r', 'при параллельном соединении делят ток поровну', 'Pmax = ℰ²/r'],
       solve=_s25cp, kes=['3.2.6', '3.2.7', '3.2.9'],
       fidelity=p2fid(25, 'КИМ: «К аккумулятору с ЭДС 50 В и внутренним сопротивлением 4 Ом подключили…»', 'ℰ 6–60 В, r 0,5–5 Ом, R 2–40 Ом',
                      'внутреннее сопротивление и распределение токов', ['3.2.6', '3.2.9'], 12))
def g25_cp(rng):
    E = rng.choice([6, 9, 12, 18, 24, 36, 50, 60])
    r = Fr(rng.choice([1, 2, 3, 4, 5, 8, 10]), 2)
    R1, R2 = rng.choice([2, 3, 4, 5, 6, 8, 10, 12, 15, 20, 30, 40]), rng.choice([2, 3, 4, 5, 6, 8, 10, 12, 15, 20, 30, 40])
    par = rng.random() < 0.5
    ask = rng.choice(['P2', 'P2', 'eta', 'Pmax'])
    src = rng.choice(['аккумулятору', 'батарее', 'источнику тока'])
    if ask == 'Pmax':
        val = float(E * E / (4 * r))
        q = (f'Реостат подключён к {src}, ЭДС которого {E} В, а внутреннее сопротивление {ru(r)} Ом. Сопротивление реостата можно менять. '
             f'Какую наибольшую мощность (в Вт) может выделять реостат? {rq(1)}')
        e = f'P = ℰ²R/(R + r)² максимальна при R = r: Pmax = ℰ²/(4r) = {sf(val)} Вт. Ответ: {{ANS}}.'
        wrong = [float(E * E / r), float(E * E / (2 * r)), float(E * E / (4 * r)) * 2]
    else:
        if par:
            Rp = Fr(R1 * R2, R1 + R2)
            I = E / (Rp + r)
            U = I * Rp
            P2 = U * U / R2
        else:
            I = E / (R1 + R2 + r)
            U = I * (R1 + R2)
            P2 = I * I * R2
        val = float(P2 if ask == 'P2' else U / E * 100)
        q = (f'Резисторы R₁ = {R1} Ом и R₂ = {R2} Ом, соединённые {"параллельно" if par else "последовательно"}, подключены к {src}; '
             f'ЭДС источника {E} В, его внутреннее сопротивление {ru(r)} Ом. ' + ('Какая мощность (в Вт) выделяется в резисторе R₂?' if ask == 'P2' else 'Каков КПД источника (в процентах)?') + f' {rq(1)}')
        e = (f'Rвнеш = {sf(Rp) if par else R1 + R2} Ом; I = ℰ/(Rвнеш + r) = {sf(I)} А; U = IRвнеш = {sf(U)} В; ' +
             (f'P₂ = {"U²/R₂" if par else "I²R₂"} = {sf(P2)} Вт' if ask == 'P2' else f'η = U/ℰ = {sf(U / E * 100)} %') + '. Ответ: {ANS}.')
        wrong = [float(E * E / R2), float((E / (R1 + R2)) ** 2 * R2) if not par else float(E * E / R2), val * 2]
    return num_card('ph-ege-25-circuit-power', q, val, 1, e, {'E': E, 'r': fr(r), 'R1': R1, 'R2': R2, 'par': par, 'ask': ask}, wrong)


# ================================================================= дополнения (2): сложные задачи части 2

def _s26inc(p):
    m, M, k, s, mu = p['m'] / 1000, p['M'] / 1000, p['k'], p['sin'], p['mu']
    c = math.sqrt(1 - s * s)
    a = (M * G10 - 2 * m * G10 * s - 2 * mu * m * G10 * c) / (M + 2 * m)
    x = m * (a + G10 * s + mu * G10 * c) / k
    return fmt({'x': x * 100, 'L': p['l0'] + x * 100}[p['ask']], p['dec'])


@proto('ph-ege-26-incline-two-bodies', 'ЕГЭ', 26, 'Два бруска, скреплённые пружиной, на наклонной плоскости тянет груз через блок: деформация/длина пружины',
       invariant='система движется с a = (Mg − 2mg sin α − 2μmg cos α)/(M + 2m); для нижнего бруска kx − mg sin α − μmg cos α = ma',
       varies='массы брусков и груза, жёсткость, угол (sin α), наличие трения, свободная длина пружины, что найти',
       answer_rule='удлинение или длина пружины в см с указанным округлением; в КИМ — с обоснованием применимости законов',
       mistakes=['kx = mg sin α (без учёта ускорения)', 'ускорение считают только по одному бруску', 'трение с sin вместо cos'],
       solve=_s26inc, kes=['1.2.4', '1.2.6', '1.2.8'],
       fidelity=p2fid(26, 'КИМ: «По неподвижной гладкой наклонной плоскости с углом α движутся два одинаковых бруска, скреплённые лёгкой пружиной… Верхний брусок соединён нитью через блок с грузом M…»',
                      'm 0,1–0,5 кг, M 0,5–3 кг, k 50–400 Н/м, sin α 0,5/0,6', 'ускорение системы, сила упругости по II закону', ['1.2.4', '1.2.8'], 20))
def g26_inc(rng):
    m = rng.choice([100, 150, 200, 250, 300, 400, 500])
    M = rng.choice([500, 800, 1000, 1500, 2000, 2500, 3000])
    k = rng.choice([50, 80, 100, 120, 150, 200, 250, 400])
    s = rng.choice([0.5, 0.6, 0.8])
    mu = rng.choice([0, 0, 0.1, 0.2, 0.25])
    l0 = rng.choice([8, 10, 12, 15, 20])
    ask = rng.choice(['x', 'L'])
    c = math.sqrt(1 - s * s)
    a = (M / 1000 * 10 - 2 * m / 1000 * 10 * (s + mu * c)) / ((M + 2 * m) / 1000)
    if a <= 0.2:
        raise Retry
    x = m / 1000 * (a + 10 * s + mu * 10 * c) / k
    val = x * 100 if ask == 'x' else l0 + x * 100
    ang = f'углом α при основании (sin α = {ru(Fr(s).limit_denominator(10))})' if s != 0.5 else 'углом при основании 30°'
    surf = 'гладкой' if mu == 0 else f'шероховатой (коэффициент трения брусков о плоскость {ru(Fr(mu).limit_denominator(100))})'
    q = (f'По неподвижной {surf} наклонной плоскости с {ang} вверх движутся два одинаковых бруска массой {mtxt(m)} каждый, соединённые лёгкой пружиной '
         f'жёсткостью {k} Н/м (длина недеформированной пружины {l0} см). Верхний брусок привязан к лёгкой нерастяжимой нити, перекинутой через невесомый блок '
         f'на вершине плоскости; к другому концу нити подвешен груз массой {mtxt(M)}. Длина пружины при движении не меняется. '
         + ('Найдите удлинение пружины (в см).' if ask == 'x' else 'Найдите длину пружины (в см) во время движения.') +
         f' Трением в оси блока пренебречь. Сделайте рисунок с указанием сил, действующих на тела.{JUST} {rq(1)}')
    e = (f'Обоснование: ИСО — Земля; тела движутся поступательно — материальные точки; нить нерастяжима, длина пружины постоянна — ускорения всех тел '
         f'одинаковы; нить и блок невесомы, трения в оси нет — натяжение нити одинаково. II закон Ньютона для системы: (M + 2m)a = Mg − 2mg sin α'
         + ('' if mu == 0 else ' − 2μmg cos α') + f' ⇒ a ≈ {sf(a)} м/с²; для нижнего бруска kx − mg sin α' + ('' if mu == 0 else ' − μmg cos α') +
         f' = ma ⇒ x ≈ {sf(x * 100)} см' + ('' if ask == 'x' else f', L = l₀ + x ≈ {sf(val)} см') + '. Ответ: {ANS}.')
    wrong = [m / 1000 * 10 * s / k * 100 + (l0 if ask == 'L' else 0), 2 * x * 100 + (l0 if ask == 'L' else 0), m / 1000 * a / k * 100 + (l0 if ask == 'L' else 0)]
    return num_card('ph-ege-26-incline-two-bodies', q, val, 1, e, {'m': m, 'M': M, 'k': k, 'sin': s, 'mu': mu, 'l0': l0, 'ask': ask}, wrong)


def _s26cone(p):
    w, tg = p['w'], Fr(p['tg'])
    r = G10 / (w * w * float(tg))
    return fmt({'r': r * 100, 'h': r / float(tg) * 100}[p['ask']], p['dec'])


@proto('ph-ege-26-rotating-cone', 'ЕГЭ', 26, 'Шайба внутри гладкого вращающегося конуса: радиус окружности или высота над вершиной',
       invariant='N sin α = mg, N cos α = mω²r (α — угол образующей с вертикалью) ⇒ r = g/(ω² tg α), h = r/tg α',
       varies='угловая скорость, угол конуса (tg α), что найти, сюжет (конус, воронка, чаша-конус)',
       answer_rule='r или h в см с указанным округлением',
       mistakes=['проецируют N на неверные оси (sin ↔ cos)', 'mω²r = mg tg α'],
       solve=_s26cone, kes=['1.1.8', '1.2.4'],
       fidelity=p2fid(26, 'КИМ: «Полый конус с углом при вершине 2α вращается вокруг вертикальной оси с угловой скоростью ω… Внутри конуса… вращается небольшое тело…»',
                      'ω 2–20 рад/с, tg α 0,5–2', 'проекции силы нормальной реакции', ['1.1.8', '1.2.4'], 20))
def g26_cone(rng):
    w = rng.choice([2, 3, 4, 5, 6, 8, 10, 12, 15, 20])
    tg = rng.choice([Fr(1, 2), Fr(3, 4), Fr(1), Fr(4, 3), Fr(2)])
    ask = rng.choice(['r', 'h'])
    r = 10 / (w * w * float(tg))
    val = r * 100 if ask == 'r' else r / float(tg) * 100
    if not 0.5 < val < 200:
        raise Retry
    obj = rng.choice(['Полый конус', 'Гладкая коническая воронка', 'Коническая чаша центрифуги'])
    q = (f'{obj} с вершиной внизу вращается вокруг своей вертикальной оси с угловой скоростью {w} рад/с. Образующая конуса составляет с осью угол α, '
         f'tg α = {ru(tg)}. Внутри на гладкой поверхности вращается вместе с конусом маленькая шайба, не смещаясь относительно него. '
         + ('Найдите радиус окружности (в см), по которой движется шайба.' if ask == 'r' else 'На какой высоте (в см) над вершиной конуса находится шайба?') +
         f' Сделайте рисунок с указанием сил.{JUST} {rq(1)}')
    e = (f'Обоснование: ИСО — Земля; шайба мала — материальная точка; движется по окружности равномерно — ускорение центростремительное, a = ω²r. '
         f'Поверхность гладкая — действуют mg и N ⟂ образующей. N sin α = mg, N cos α = mω²r ⇒ r = g/(ω² tg α) ≈ {sf(r * 100)} см; h = r/tg α ≈ {sf(r / float(tg) * 100)} см. Ответ: {{ANS}}.')
    wrong = [10 * float(tg) / (w * w) * 100, 10 / (w * w) * 100, val * 2]
    return num_card('ph-ege-26-rotating-cone', q, val, 1, e, {'w': w, 'tg': fr(tg), 'ask': ask}, wrong)


LIQ24 = [('бензол', 'C₆H₆', 80, 396000, 0.078), ('этиловый спирт', 'C₂H₅OH', 78, 846000, 0.046), ('ацетон', 'C₃H₆O', 56, 524000, 0.058),
         ('вода', 'H₂O', 100, 2300000, 0.018), ('эфир', 'C₄H₁₀O', 35, 355000, 0.074)]


def _s24ev(p):
    _, _, t, L, M = [x for x in LIQ24 if x[0] == p['liq']][0]
    T = t + 273
    m = p['Q'] / L
    A = m * R_ * T / M
    return fmt({'A': A, 'dh': A / (1e5 * p['S'] / 10000) * 100, 'm': m * 1000}[p['ask']], p['dec'])


@proto('ph-ege-24-evaporation-piston', 'ЕГЭ', 24, 'Жидкость при температуре кипения под лёгким поршнем: работа пара, подъём поршня, масса испарившейся жидкости',
       invariant='Q = Lm; пар при p = p₀ — идеальный газ: A = pΔV = (m/M)RT; Δh = A/(p₀S)',
       varies='жидкость (бензол, спирт, ацетон, вода, эфир — L, M, tкип), сообщённая теплота, площадь поршня, что найти',
       answer_rule='A в Дж, Δh в см или m в г с указанным округлением',
       mistakes=['температура в °C', 'A = Q', 'не учитывают, что работу совершает только образовавшийся пар'],
       solve=_s24ev, kes=['2.1.10', '2.1.15', '2.2.5', '2.2.6'],
       fidelity=p2fid(24, 'КИМ: «В вертикальном цилиндре, закрытом лёгким поршнем, находится бензол при температуре кипения… часть его превращается в пар…»',
                      'Q 10²–10⁴ Дж, L и M — в условии, p₀ = 10⁵ Па', 'пар как идеальный газ, связь Q и массы пара', ['2.1.15', '2.2.5'], 15))
def g24_ev(rng):
    liq, form, t, L, M = rng.choice(LIQ24)
    Q = rng.choice([200, 400, 500, 800, 1000, 1500, 2000, 3000, 5000])
    S = rng.choice([10, 20, 25, 50, 100])
    ask = rng.choice(['A', 'dh', 'm'])
    T = t + 273
    m = Q / L
    A = m * R_ * T / M
    val = {'A': A, 'dh': A / (1e5 * S / 10000) * 100, 'm': m * 1000}[ask]
    if val < 0.1 or (ask == 'dh' and val > 300):
        raise Retry
    Lt = f'{ru(Fr(L, 1000))}·10³'
    q = (f'В вертикальном цилиндре{" площадью сечения " + str(S) + " см²" if ask == "dh" else ""}, закрытом лёгким подвижным поршнем, находится {liq} ({form}) '
         f'при температуре кипения {t} °C; над жидкостью пара нет, атмосферное давление 10⁵ Па. Жидкости сообщают количество теплоты {Q} Дж, часть её '
         f'превращается в пар, который, расширяясь изобарно, поднимает поршень. Удельная теплота парообразования {Lt} Дж/кг, молярная масса '
         f'{ru(Fr(M).limit_denominator(1000) * 1000)}·10⁻³ кг/моль. ' +
         {'A': 'Какую работу (в Дж) совершил пар?', 'dh': 'На какую высоту (в см) поднялся поршень?', 'm': 'Какая масса жидкости (в г) превратилась в пар?'}[ask] +
         f' Пар считать идеальным газом, теплообменом с окружающей средой пренебречь. {rq(2)}')
    e = (f'Теплота идёт на парообразование: m = Q/L = {sf(m)} кг. Пар при p₀ и T = {T} К: A = p₀ΔV = (m/M)RT ≈ {sf(A)} Дж' +
         (f'; Δh = A/(p₀S) ≈ {sf(val)} см' if ask == 'dh' else '') + '. Ответ: {ANS}.')
    wrong = {'A': [Q, m * R_ * t / M, A * 2], 'dh': [Q / (1e5 * S / 10000) * 100, val * 2, m * R_ * t / M / (1e5 * S / 10000) * 100],
             'm': [Q / L * 1e6, (Q - A) / L * 1000 * 2, val * 2]}[ask]
    return num_card('ph-ege-24-evaporation-piston', q, val, 2, e, {'liq': liq, 'Q': Q, 'S': S, 'ask': ask}, wrong)


def _s25cb(p):
    C1, C2, U = Fr(p['C1']), Fr(p['C2']), Fr(p['U'])
    if p['sit'] == 'share':
        Uf = C1 * U / (C1 + C2)
        return fmt(float({'U': Uf, 'Q': (C1 * U * U / 2 - (C1 + C2) * Uf * Uf / 2) / 1000, 'q2': C2 * Uf}[p['ask']]), p['dec'])
    if p['sit'] == 'series':
        C = C1 * C2 / (C1 + C2)
        q = C * U
        return fmt(float({'U': q / C2, 'Q': C * U * U / 2000, 'q2': q}[p['ask']]), p['dec'])
    # смешанная батарея: C1 последовательно с (C2 || C3), C3 = C2
    C3 = Fr(p['C3'])
    Cp = C2 + C3
    C = C1 * Cp / (C1 + Cp)
    q = C * U
    return fmt(float({'U': q / Cp, 'Q': C * U * U / 2000, 'q2': q / Cp * C2}[p['ask']]), p['dec'])


@proto('ph-ege-25-capacitor-battery', 'ЕГЭ', 25, 'Соединения конденсаторов: перезарядка заряженного конденсатора на незаряженный, последовательная и смешанная батареи',
       invariant='сохранение заряда при соединении; Cпосл = C₁C₂/(C₁ + C₂), Cпар = C₁ + C₂; заряд последовательных одинаков; Q = W₁ − W₂',
       varies='схема (перезарядка, последовательно к источнику, C₁ последовательно с параллельными C₂, C₃), ёмкости, напряжение, что найти',
       answer_rule='напряжение в В, заряд в мкКл или теплота/энергия в мДж с указанным округлением',
       mistakes=['энергия сохраняется при перезарядке', 'складывают ёмкости последовательных конденсаторов', 'напряжения делят поровну'],
       solve=_s25cb, kes=['3.1.9', '3.1.10', '3.1.11'],
       fidelity=p2fid(25, 'КИМ: «Конденсатор C₁ заряжен до напряжения 300 В и включён в цепь с незаряженным конденсатором C₂…», «Батарея из конденсаторов…»',
                      'C 0,5–20 мкФ, U 10–500 В', 'закон сохранения заряда, потери энергии', ['3.1.9', '3.1.10', '3.1.11'], 15))
def g25_cb(rng):
    sit = rng.choice(['share', 'series', 'mixed'])
    C1, C2 = rng.choice([1, 2, 3, 4, 5, 6, 10, 20]), rng.choice([1, 2, 3, 4, 5, 6, 10, 20])
    C3 = rng.choice([1, 2, 3, 4, 6]) if sit == 'mixed' else 0
    U = rng.choice([10, 20, 30, 50, 60, 100, 120, 200, 300, 500])
    ask = rng.choice(['U', 'Q', 'q2'])
    p = {'C1': C1, 'C2': C2, 'C3': C3, 'U': U, 'sit': sit, 'ask': ask, 'dec': 1}
    if sit == 'share':
        Uf = Fr(C1 * U, C1 + C2)
        vals = {'U': Uf, 'Q': Fr(C1) * U * U / 2 - (C1 + C2) * Uf * Uf / 2, 'q2': C2 * Uf}
        q = (f'Конденсатор ёмкостью C₁ = {C1} мкФ зарядили до напряжения {U} В, отключили от источника и соединили параллельно с незаряженным конденсатором '
             f'ёмкостью C₂ = {C2} мкФ (одноимённо — обкладка к обкладке). ')
        e0 = f'Заряд сохраняется: C₁U = (C₁ + C₂)U′ ⇒ U′ = {sf(Uf)} В; q₂ = C₂U′ = {sf(C2 * Uf)} мкКл; Q = C₁U²/2 − (C₁ + C₂)U′²/2 = {sf(vals["Q"] / 1000)} мДж.'
    elif sit == 'series':
        C = Fr(C1 * C2, C1 + C2)
        qq = C * U
        vals = {'U': qq / C2, 'Q': C * U * U / 2, 'q2': qq}
        q = f'Два незаряженных конденсатора ёмкостями C₁ = {C1} мкФ и C₂ = {C2} мкФ соединили последовательно и подключили к источнику постоянного напряжения {U} В. '
        e0 = f'C = C₁C₂/(C₁ + C₂) = {sf(C)} мкФ; заряд каждого q = CU = {sf(qq)} мкКл; U₂ = q/C₂ = {sf(qq / C2)} В; W = CU²/2 = {sf(C * U * U / 2 / 1000)} мДж.'
    else:
        Cp = C2 + C3
        C = Fr(C1 * Cp, C1 + Cp)
        qq = C * U
        vals = {'U': qq / Cp, 'Q': C * U * U / 2, 'q2': qq / Cp * C2}
        q = (f'Батарея составлена из конденсатора C₁ = {C1} мкФ, соединённого последовательно с группой из двух параллельно соединённых конденсаторов '
             f'C₂ = {C2} мкФ и C₃ = {C3} мкФ. Батарею подключили к источнику постоянного напряжения {U} В. ')
        e0 = f'C₂₃ = C₂ + C₃ = {Cp} мкФ; C = C₁C₂₃/(C₁ + C₂₃) = {sf(C)} мкФ; q = CU = {sf(qq)} мкКл; U₂₃ = q/C₂₃ = {sf(qq / Cp)} В; q₂ = C₂U₂₃ = {sf(qq / Cp * C2)} мкКл; W = CU²/2 = {sf(C * U * U / 2000)} мДж.'
    what = {'U': ('Какое напряжение (в В) установится на конденсаторе C₂?' if sit != 'share' else 'Какое напряжение (в В) установится на конденсаторах?'),
            'Q': ('Какое количество теплоты (в мДж) выделится при перезарядке?' if sit == 'share' else 'Какова энергия (в мДж) заряженной батареи?'),
            'q2': 'Каким станет заряд конденсатора C₂ (в мкКл)?'}[ask]
    val = float(vals[ask] / (1000 if ask == 'Q' else 1))
    if val < 0.1:
        raise Retry
    q += f'{what} {rq(1)}'
    e = e0 + ' Ответ: {ANS}.'
    wrong = [float(U) / 2, float(C1 * U) / 1000 if ask == 'Q' else float(C1 * U), val * 2, float(vals['U']) * C1 if ask == 'q2' else None]
    return num_card('ph-ege-25-capacitor-battery', q, val, 1, e, {k: v for k, v in p.items() if k != 'dec'}, wrong)


PC25 = {'протон': (1.67e-27, 1.6e-19, '1,67·10⁻²⁷', '1,6·10⁻¹⁹'), 'электрон': (9.1e-31, 1.6e-19, '9,1·10⁻³¹', '1,6·10⁻¹⁹'),
        'α-частица': (6.64e-27, 3.2e-19, '6,64·10⁻²⁷', '3,2·10⁻¹⁹'), 'дейтрон': (3.34e-27, 1.6e-19, '3,34·10⁻²⁷', '1,6·10⁻¹⁹')}


def _s25pc(p):
    m, q = PC25[p['part']][:2]
    l, d, U = p['l'] / 100, p['d'] / 1000, p['U']
    a = q * U / (m * d)
    if p['ask'] == 'vmin':
        return fmt(l * math.sqrt(a / d) / 1000, p['dec'])
    t = l / (p['v'] * 1000)
    return fmt(a * t * t / 2 * 1000, p['dec'])


@proto('ph-ege-25-particle-in-capacitor', 'ЕГЭ', 25, 'Заряженная частица влетает в плоский конденсатор параллельно пластинам: минимальная скорость вылета или смещение',
       invariant='вдоль пластин — равномерно: t = l/υ; поперёк — равноускоренно, a = qU/(md); вылет при d/2 ≥ at²/2 ⇒ υmin = (l/d)√(qU/m)',
       varies='частица (протон, электрон, α, дейтрон), длина пластин, зазор, напряжение, начальная скорость, что найти',
       answer_rule='скорость в км/с или смещение в мм с указанным округлением',
       mistakes=['a = qU/m (без d)', 'смещение сравнивают с d вместо d/2', 'учитывают силу тяжести'],
       solve=_s25pc, kes=['3.1.3', '3.1.5', '1.1.8'],
       fidelity=p2fid(25, 'КИМ: «Протон влетает в электрическое поле конденсатора параллельно его пластинам в точке посередине между пластинами… Найдите минимальную скорость…»',
                      'l 2–10 см, d 5–20 мм, U 10–1000 В', 'движение как бросок: вдоль и поперёк поля', ['3.1.3', '1.1.8'], 15))
def g25_pc(rng):
    part = rng.choice(list(PC25))
    m, qe, mt, qt = PC25[part]
    l = rng.choice([2, 3, 4, 5, 6, 8, 10])
    d = rng.choice([5, 8, 10, 12, 15, 20])
    U = rng.choice([10, 20, 50, 100, 200, 500, 1000]) if part != 'электрон' else rng.choice([1, 2, 5, 10, 20, 50])
    ask = rng.choice(['vmin', 'y'])
    a = qe * U / (m * d / 1000)
    vmin = l / 100 * math.sqrt(a / (d / 1000))
    if ask == 'vmin':
        val = vmin / 1000
        q = (f'{cap1(part)} (масса {mt} кг, модуль заряда {qt} Кл) влетает в электрическое поле плоского конденсатора параллельно его пластинам в точке, '
             f'равноудалённой от них. Длина пластин {l} см, расстояние между ними {d} мм, напряжение между пластинами {U} В. С какой минимальной скоростью '
             f'(в км/с) частица должна влететь в конденсатор, чтобы затем вылететь из него? Силой тяжести пренебречь. {rq(0 if val >= 10 else 1)}')
        v = 0
    else:
        v = round(vmin / 1000 * rng.choice([1.2, 1.5, 2, 3]), -1 if vmin > 10000 else 0) or 1
        val = a * (l / 100 / (v * 1000)) ** 2 / 2 * 1000
        if val >= d / 2:
            raise Retry
        q = (f'{cap1(part)} (масса {mt} кг, модуль заряда {qt} Кл) влетает со скоростью {ru(Fr(v).limit_denominator(10))} км/с в поле плоского конденсатора '
             f'параллельно пластинам посередине между ними. Длина пластин {l} см, расстояние между пластинами {d} мм, напряжение {U} В. На сколько миллиметров '
             f'сместится частица поперёк пластин к моменту вылета из конденсатора? Силой тяжести пренебречь. {rq(2)}')
    dec = (0 if val >= 10 else 1) if ask == 'vmin' else 2
    if val < 0.01 or val > 1e6:
        raise Retry
    e = (f'Вдоль пластин движение равномерное: t = l/υ; поперёк — равноускоренное с a = qU/(md) = {sf(a)} м/с². ' +
         (f'Частица вылетает, если at²/2 ≤ d/2 ⇒ υmin = (l/d)·√(qU/m) ≈ {sf(vmin)} м/с.' if ask == 'vmin' else f'y = at²/2 ≈ {sf(val)} мм.') + ' Ответ: {ANS}.')
    wrong = [val * math.sqrt(2), val * 2, val / 2] if ask == 'vmin' else [val * 2, val / 2, a * (l / 100 / (v * 1000)) * 1000]
    return num_card('ph-ege-25-particle-in-capacitor', q, val, dec, e, {'part': part, 'l': l, 'd': d, 'U': U, 'v': v, 'ask': ask}, wrong)
